import { z } from "zod";

const dealRegionSchema = z.enum(["INDIA", "CANADA", "WORLD"]);

// Deal Schemas
export const createDealSchema = z.object({
  title: z.string().min(5).max(200),
  description: z.string().max(2000).optional(),
  originalPrice: z.number().positive().optional(),
  dealPrice: z.number().positive().optional(),
  discountPercent: z.number().int().min(0).max(100).optional(),
  productUrl: z
    .string()
    .url()
    .refine((url) => url.startsWith("https://"), {
      message: "Only HTTPS URLs are allowed",
    }),
  imageUrl: z.string().url().optional(),
  store: z.string().max(100).optional(),
  categoryId: z.string().cuid(),
  region: dealRegionSchema,
});

export const updateDealSchema = createDealSchema.partial();

export const dealQuerySchema = z.object({
  page: z.coerce.number().int().positive().default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
  category: z.string().optional(),
  store: z.string().max(200).optional(),
  minDiscount: z.coerce.number().int().min(0).max(100).optional(),
  search: z.string().max(200).optional(),
  sortBy: z.enum(["newest", "popular", "discount"]).default("newest"),
  region: dealRegionSchema.optional(),
  source: z.enum(["REDDIT", "USER_SUBMITTED"]).optional(),
  status: z.enum(["ACTIVE", "EXPIRED", "REJECTED"]).optional(),
  showInactive: z.coerce.boolean().optional(),
});

// User Schemas

export const updatePreferencesSchema = z.object({
  emailNotifications: z.boolean().optional(),
  pushNotifications: z.boolean().optional(),
  preferredCategories: z.array(z.string().cuid()).optional(),
  minDiscountPercent: z.number().int().min(0).max(100).optional(),
});

// Comment Schemas

export const createCommentSchema = z.object({
  content: z.string().min(1).max(1000),
  parentId: z.string().cuid().optional(),
});

export const updateCommentSchema = z.object({
  content: z.string().min(1).max(1000),
});

// Badge Schemas (admin only)

export const createBadgeSchema = z.object({
  name: z.string().min(2).max(100),
  slug: z
    .string()
    .min(2)
    .max(100)
    .regex(/^[a-z0-9-]+$/),
  icon: z.string().min(1).max(10),
  description: z.string().min(5).max(500),
  tier: z.enum(["BRONZE", "SILVER", "GOLD", "PLATINUM"]),
  criteria: z.object({
    type: z.string(),
    threshold: z.number().int().min(0),
  }),
});

// Challenge Schemas (admin only)

export const createChallengeSchema = z.object({
  title: z.string().min(3).max(200),
  description: z.string().min(5).max(1000),
  criteria: z.object({
    category: z.string().optional(),
    maxPrice: z.number().positive().optional(),
    minDiscount: z.number().int().min(0).max(100).optional(),
  }),
  startDate: z.string().datetime(),
  endDate: z.string().datetime(),
});

// Price Alert Schemas

const alertModeSchema = z.enum(["KEYWORD", "URL"]);
const httpsUrlSchema = z
  .string()
  .url()
  .refine((url) => url.startsWith("https://"), {
    message: "Only HTTPS URLs are allowed",
  });

export const createAlertSchema = z.object({
  mode: alertModeSchema.default("KEYWORD"),
  keywords: z.string().min(2).max(200).optional(),
  watchUrl: httpsUrlSchema.optional(),
  maxPrice: z.number().positive().optional(),
  categoryId: z.string().cuid().optional(),
  region: dealRegionSchema.optional(),
}).superRefine((data, ctx) => {
  if (data.mode === "URL") {
    if (!data.watchUrl) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ["watchUrl"],
        message: "Product URL is required for URL watchlists",
      });
    }
    return;
  }

  if (!data.keywords?.trim()) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      path: ["keywords"],
      message: "Keywords are required for keyword alerts",
    });
  }
});

export const updateAlertSchema = z.object({
  mode: alertModeSchema.optional(),
  keywords: z.string().min(2).max(200).optional(),
  watchUrl: httpsUrlSchema.optional().nullable(),
  maxPrice: z.number().positive().optional().nullable(),
  categoryId: z.string().cuid().optional().nullable(),
  region: dealRegionSchema.optional().nullable(),
});

// Common Response Types

export interface PaginatedResponse<T> {
  data: T[];
  pagination: {
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  };
}

export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  error?: string;
}

// Type exports
export type CreateDealInput = z.infer<typeof createDealSchema>;
export type UpdateDealInput = z.infer<typeof updateDealSchema>;
export type DealQueryInput = z.infer<typeof dealQuerySchema>;
export type UpdatePreferencesInput = z.infer<typeof updatePreferencesSchema>;
export type CreateCommentInput = z.infer<typeof createCommentSchema>;
export type UpdateCommentInput = z.infer<typeof updateCommentSchema>;
export type CreateBadgeInput = z.infer<typeof createBadgeSchema>;
export type CreateChallengeInput = z.infer<typeof createChallengeSchema>;
export type CreateAlertInput = z.infer<typeof createAlertSchema>;
export type UpdateAlertInput = z.infer<typeof updateAlertSchema>;

import { useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { User } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { User as AuthUser } from "@/store/authStore";
import { cn } from "@/lib/utils";

interface AuthUserMenuItem {
  to: string;
  label: string;
}

interface AuthUserMenuProps {
  user: AuthUser | null;
  onLogout: () => Promise<void>;
  items?: AuthUserMenuItem[];
}

const defaultMenuItems: AuthUserMenuItem[] = [
  { to: "/alerts", label: "Price Alerts" },
  { to: "/leaderboard", label: "Leaderboard" },
  { to: "/settings", label: "Settings" },
];

export function AuthUserMenu({
  user,
  onLogout,
  items = defaultMenuItems,
}: AuthUserMenuProps) {
  const [open, setOpen] = useState(false);

  const avatarInitial = useMemo(() => {
    const source = user?.name?.trim() || user?.email?.trim() || "";
    return source ? source.charAt(0).toUpperCase() : null;
  }, [user?.email, user?.name]);

  const menuItemClass =
    "min-h-10 rounded-[16px] border border-transparent bg-white/0 px-3 py-0 text-[13px] font-medium leading-none tracking-[-0.01em] text-foreground outline-none will-change-transform transition-[transform,background-color,border-color,color,box-shadow] duration-150 ease-out hover:-translate-y-[1px] hover:border-black/6 hover:bg-white/72 hover:shadow-[0_14px_24px_-22px_rgba(15,23,42,0.18)] data-[highlighted]:-translate-y-[1px] data-[highlighted]:border-black/6 data-[highlighted]:bg-white/72 data-[highlighted]:text-foreground data-[highlighted]:shadow-[0_14px_24px_-22px_rgba(15,23,42,0.18)] active:scale-[0.985] sm:min-h-10 sm:rounded-[14px] sm:px-3.5 sm:text-[13.5px]";

  const handleLogout = async () => {
    setOpen(false);
    await onLogout();
  };

  return (
    <DropdownMenu open={open} onOpenChange={setOpen}>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          className={cn(
            "relative h-8 w-8 rounded-full p-0 transition-[transform,background-color,box-shadow] duration-200 hover:-translate-y-[1px] sm:h-10 sm:w-10",
            open
              ? "surface-liquid-chip bg-white/22 shadow-[0_16px_28px_-24px_rgba(15,23,42,0.26)]"
              : "hover:bg-white/18",
          )}
          title="Account menu"
          aria-label="Account menu"
        >
          <span className="block h-8 w-8 overflow-hidden rounded-full sm:h-10 sm:w-10">
            {user?.avatarUrl ? (
              <img
                src={user.avatarUrl}
                alt={user?.name || "User"}
                className="h-full w-full object-cover"
                loading="lazy"
                decoding="async"
              />
            ) : (
              <span className="inline-flex h-full w-full items-center justify-center bg-secondary text-sm font-semibold text-foreground">
                {avatarInitial ?? <User className="h-4 w-4" />}
              </span>
            )}
          </span>
        </Button>
      </DropdownMenuTrigger>

      <DropdownMenuContent
        align="end"
        side="bottom"
        sideOffset={8}
        collisionPadding={{ top: 12, right: 8, bottom: 12, left: 8 }}
        className="surface-auth-menu isolate z-[70] w-[calc(100vw-1rem)] max-w-[13.25rem] overflow-hidden rounded-[24px] p-1 sm:w-[13.75rem] sm:p-1.5"
      >
        <div className="pointer-events-none absolute inset-x-0 top-0 h-24 bg-[radial-gradient(circle_at_top_right,rgba(251,191,36,0.14),transparent_34%),radial-gradient(circle_at_top_left,rgba(244,114,182,0.1),transparent_38%)]" />

        <div className="relative z-10">
          <div className="border-b border-black/[0.05] px-3 py-2.5 sm:px-3.5 sm:py-3">
            {user?.name ? (
              <p className="text-[15px] font-semibold leading-tight tracking-[-0.02em] sm:text-base">
                {user.name}
              </p>
            ) : null}
            {user?.email ? (
              <p className="truncate pt-0.5 text-[12px] text-muted-foreground sm:text-sm">
                {user.email}
              </p>
            ) : null}
          </div>

          <div className="space-y-0.5 px-1 py-1 sm:px-0 sm:py-1">
            {items.map((item) => (
              <DropdownMenuItem asChild className={menuItemClass} key={item.to}>
                <Link to={item.to}>{item.label}</Link>
              </DropdownMenuItem>
            ))}
          </div>

          <DropdownMenuSeparator className="mx-1 bg-black/[0.05] sm:mx-0" />

          <div className="px-1 pb-1 sm:px-0 sm:pb-0">
            <DropdownMenuItem
              onSelect={() => {
                void handleLogout();
              }}
              className="min-h-10 rounded-[16px] border border-transparent bg-white/0 px-3 py-0 text-[13px] font-medium leading-none tracking-[-0.01em] text-destructive outline-none will-change-transform transition-[transform,background-color,border-color,color,box-shadow] duration-150 ease-out hover:-translate-y-[1px] hover:border-rose-200/85 hover:bg-rose-500/10 hover:shadow-[0_14px_24px_-22px_rgba(244,63,94,0.22)] data-[highlighted]:-translate-y-[1px] data-[highlighted]:border-rose-200/85 data-[highlighted]:bg-rose-500/10 data-[highlighted]:text-destructive data-[highlighted]:shadow-[0_14px_24px_-22px_rgba(244,63,94,0.22)] active:scale-[0.985] sm:min-h-10 sm:rounded-[14px] sm:px-3.5 sm:text-[13.5px]"
            >
              Log out
            </DropdownMenuItem>
          </div>
        </div>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export default AuthUserMenu;

import { type ReactNode, useEffect } from "react";
import { Navigate } from "react-router-dom";
import { useAuthStore } from "@/store/authStore";
import { Loader2 } from "lucide-react";

interface ProtectedRouteProps {
  children: ReactNode;
}

export function ProtectedRoute({ children }: ProtectedRouteProps) {
  const {
    isAuthenticated,
    isLoading,
    hasAttemptedSessionRestore,
    checkAuth,
  } = useAuthStore();

  useEffect(() => {
    if (!isAuthenticated && !isLoading && !hasAttemptedSessionRestore) {
      void checkAuth({ force: true });
    }
  }, [checkAuth, hasAttemptedSessionRestore, isAuthenticated, isLoading]);

  if (isLoading || (!isAuthenticated && !hasAttemptedSessionRestore)) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center">
        <Loader2 className="h-10 w-10 animate-spin text-primary mb-4" />
        <p className="text-muted-foreground">Loading...</p>
      </div>
    );
  }

  if (!isAuthenticated) {
    return <Navigate to="/" replace />;
  }

  return <>{children}</>;
}

export default ProtectedRoute;

import { useEffect } from "react";
import { useLocation } from "react-router-dom";

interface PageMetaOptions {
  title: string;
  description: string;
  canonicalPath?: string;
  type?: "website" | "article";
}

const SITE_URL = (import.meta.env.VITE_SITE_URL || "https://savekaro.online").replace(/\/$/, "");

function ensureMeta(selector: string, create: () => HTMLMetaElement): HTMLMetaElement {
  const existing = document.head.querySelector<HTMLMetaElement>(selector);
  if (existing) {
    return existing;
  }

  const element = create();
  document.head.appendChild(element);
  return element;
}

function ensureLink(selector: string, create: () => HTMLLinkElement): HTMLLinkElement {
  const existing = document.head.querySelector<HTMLLinkElement>(selector);
  if (existing) {
    return existing;
  }

  const element = create();
  document.head.appendChild(element);
  return element;
}

function buildAbsoluteUrl(path: string): string {
  if (/^https?:\/\//i.test(path)) {
    return path;
  }

  const normalizedPath = path.startsWith("/") ? path : `/${path}`;
  return `${SITE_URL}${normalizedPath}`;
}

export function usePageMeta({
  title,
  description,
  canonicalPath,
  type = "website",
}: PageMetaOptions) {
  const location = useLocation();

  useEffect(() => {
    const pageTitle = title.includes("SaveKaro") ? title : `${title} | SaveKaro`;
    const url = buildAbsoluteUrl(canonicalPath ?? location.pathname);

    document.title = pageTitle;

    const descriptionMeta = ensureMeta('meta[name="description"]', () => {
      const meta = document.createElement("meta");
      meta.name = "description";
      return meta;
    });
    descriptionMeta.content = description;

    const canonicalLink = ensureLink('link[rel="canonical"]', () => {
      const link = document.createElement("link");
      link.rel = "canonical";
      return link;
    });
    canonicalLink.href = url;

    const ogTitle = ensureMeta('meta[property="og:title"]', () => {
      const meta = document.createElement("meta");
      meta.setAttribute("property", "og:title");
      return meta;
    });
    ogTitle.content = pageTitle;

    const ogDescription = ensureMeta('meta[property="og:description"]', () => {
      const meta = document.createElement("meta");
      meta.setAttribute("property", "og:description");
      return meta;
    });
    ogDescription.content = description;

    const ogUrl = ensureMeta('meta[property="og:url"]', () => {
      const meta = document.createElement("meta");
      meta.setAttribute("property", "og:url");
      return meta;
    });
    ogUrl.content = url;

    const ogType = ensureMeta('meta[property="og:type"]', () => {
      const meta = document.createElement("meta");
      meta.setAttribute("property", "og:type");
      return meta;
    });
    ogType.content = type;

    const twitterTitle = ensureMeta('meta[name="twitter:title"]', () => {
      const meta = document.createElement("meta");
      meta.name = "twitter:title";
      return meta;
    });
    twitterTitle.content = pageTitle;

    const twitterDescription = ensureMeta('meta[name="twitter:description"]', () => {
      const meta = document.createElement("meta");
      meta.name = "twitter:description";
      return meta;
    });
    twitterDescription.content = description;
  }, [canonicalPath, description, location.pathname, title, type]);
}

export default usePageMeta;

import { useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { useAuthStore } from "@/store/authStore";
import { Loader2 } from "lucide-react";

export function AuthCallback() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { login } = useAuthStore();

  useEffect(() => {
    // Read the one-time auth code from URL (not a JWT!)
    const code = searchParams.get("code");

    if (code) {
      login(code)
        .then(() => {
          navigate("/", { replace: true });
        })
        .catch(() => {
          navigate("/auth/error?message=Login failed. Please try again.", {
            replace: true,
          });
        });
    } else {
      navigate("/auth/error?message=No auth code received", { replace: true });
    }
  }, [searchParams, login, navigate]);

  return (
    <div className="min-h-screen flex flex-col items-center justify-center">
      <Loader2 className="h-12 w-12 animate-spin text-primary mb-4" />
      <h1 className="text-xl font-semibold">Signing you in...</h1>
      <p className="text-muted-foreground">
        Please wait while we complete your authentication.
      </p>
    </div>
  );
}

export function AuthError() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const message =
    searchParams.get("message") || "An error occurred during authentication";

  return (
    <div className="min-h-screen flex flex-col items-center justify-center">
      <div className="text-6xl mb-4">😕</div>
      <h1 className="text-2xl font-bold mb-2">Authentication Failed</h1>
      <p className="text-muted-foreground mb-6 text-center max-w-md">
        {message}
      </p>
      <button
        onClick={() => navigate("/")}
        className="px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90"
      >
        Back to Home
      </button>
    </div>
  );
}

export default AuthCallback;

import { Hono } from "hono";
import { cors } from "hono/cors";
import { compress } from "hono/compress";
import { logger as honoLogger } from "hono/logger";
import { secureHeaders } from "hono/secure-headers";

import logger from "./lib/logger";
import prisma from "./lib/prisma";
import { isRedisHealthy } from "./lib/redis";
import { cacheGet, cacheSet } from "./lib/cache";
import { authMiddleware } from "./middleware/auth";
import { rateLimiter } from "./middleware/rate-limiter";
import { requestId } from "./middleware/request-id";
import { successResponse } from "./lib/responses";
import { CACHE_TTL } from "./config/constants";
import { setPublicCacheHeaders } from "./lib/http-cache";

import authRoutes from "./routes/auth";
import dealRoutes from "./routes/deals";
import userRoutes from "./routes/users";
import categoryRoutes from "./routes/categories";
import commentRoutes from "./routes/comments";
import notificationRoutes from "./routes/notifications";
import gamificationRoutes from "./routes/gamification";
import alertRoutes from "./routes/alerts";
import dealPreviewRoutes from "./routes/deal-preview";

import {
  createScrapeWorker,
  createEmailWorker,
  createTitleClassifierWorker,
  scheduleScrapeJobs,
} from "./services/queues";

import { scheduleTitleClassifierJobs } from "./services/queues";
import { startScheduler, stopScheduler } from "./services/reddit/scheduler";
import { stopTitleClassifierScheduler } from "./services/title-classifier";
import { startTitleClassifierScheduler } from "./services/title-classifier";
import { signalRedditShutdown } from "./services/reddit/client";
import { captureServerException, shutdownAnalytics } from "./lib/posthog";

const app = new Hono();
let shutdownPromise: Promise<void> | null = null;

app.use("*", requestId);
app.use("*", honoLogger());
app.use("*", secureHeaders());
app.use(
  "*",
  cors({
    origin: (origin) => {
      const allowed = [
        process.env.FRONTEND_URL,
        "https://savekaro.online",
        "http://localhost:5173",
      ].filter(Boolean);
      if (!origin) return process.env.FRONTEND_URL || "https://savekaro.online";
      if (allowed.includes(origin)) return origin;
      return process.env.FRONTEND_URL || "https://savekaro.online";
    },
    credentials: true,
    allowMethods: ["GET", "POST", "PUT", "DELETE", "OPTIONS"],
    allowHeaders: [
      "Content-Type",
      "Authorization",
      "Cookie",
      "X-SaveKaro-Analytics-Consent",
      "X-PostHog-Distinct-Id",
      "X-PostHog-Session-Id",
      "X-PostHog-Window-Id",
    ],
    exposeHeaders: ["Set-Cookie", "X-Request-Id"],
  }),
);

app.use("/api/*", rateLimiter);

app.use(
  "/api/*",
  compress({
    threshold: 1024,
  }),
);

app.use("/api/*", authMiddleware);

app.get("/health", async (c) => {
  const checks: Record<string, string> = {};

  try {
    await prisma.$queryRaw`SELECT 1`;
    checks.database = "ok";
  } catch {
    checks.database = "error";
  }

  if (process.env.USE_QUEUE === "true") {
    checks.redis = (await isRedisHealthy()) ? "ok" : "error";
  }

  const allHealthy = Object.values(checks).every((v) => v === "ok");

  return c.json(
    {
      status: allHealthy ? "ok" : "degraded",
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      checks,
    },
    allHealthy ? 200 : 503,
  );
});

app.route("/", dealPreviewRoutes);
app.route("/api/auth", authRoutes);
app.route("/api/deals", dealRoutes);
app.route("/api/users", userRoutes);
app.route("/api/categories", categoryRoutes);
app.route("/api/comments", commentRoutes);
app.route("/api/notifications", notificationRoutes);
app.route("/api/gamification", gamificationRoutes);
app.route("/api/alerts", alertRoutes);

app.get("/api/stats", async (c) => {
  setPublicCacheHeaders(c, {
    maxAge: CACHE_TTL.STATS,
    sMaxAge: CACHE_TTL.STATS,
    staleWhileRevalidate: CACHE_TTL.STATS,
    staleIfError: CACHE_TTL.STATS * 10,
  });

  const cacheKey = "stats:global";
  const cached = await cacheGet<any>(cacheKey);
  if (cached) return c.json(cached);

  const [dealCount, userCount, categoryStats] = await Promise.all([
    prisma.deal.count({ where: { isActive: true } }),
    prisma.user.count(),
    prisma.category.findMany({
      include: {
        _count: {
          select: { deals: { where: { isActive: true } } },
        },
      },
    }),
  ]);

  const response = successResponse({
    totalDeals: dealCount,
    totalUsers: userCount,
    categories: categoryStats.map((cat: any) => ({
      name: cat.name,
      slug: cat.slug,
      dealCount: cat._count.deals,
    })),
  });

  await cacheSet(cacheKey, response, CACHE_TTL.STATS);
  return c.json(response);
});

app.notFound((c) => {
  return c.json(
    {
      success: false,
      error: "Not found",
    },
    404,
  );
});

app.onError((err, c) => {
  logger.error({ error: err }, "Unhandled error");
  captureServerException(c, err);
  return c.json(
    {
      success: false,
      error:
        process.env.NODE_ENV === "production"
          ? "Internal server error"
          : err.message,
    },
    500,
  );
});

const PORT = parseInt(process.env.PORT || "3001");
const USE_QUEUE = process.env.USE_QUEUE === "true";

async function main() {
  try {
    await prisma.$connect();
    logger.info("Database connected");

    const { ensureDefaultCategories } = await import("./services/bootstrap");
    await ensureDefaultCategories();

    if (USE_QUEUE) {
      const scrapeWorker = createScrapeWorker();
      const emailWorker = createEmailWorker();
      const titleClassifierWorker = process.env.GEMINI_API_KEY
        ? createTitleClassifierWorker()
        : null;

      await scheduleScrapeJobs();
      if (titleClassifierWorker) {
        await scheduleTitleClassifierJobs();
      } else {
        logger.warn(
          "GEMINI_API_KEY is not configured — title classifier worker not started",
        );
      }

      logger.info("Job queue workers started");

      (globalThis as Record<string, unknown>).__workers = [
        scrapeWorker,
        emailWorker,
        ...(titleClassifierWorker ? [titleClassifierWorker] : []),
      ];
    } else if (process.env.NODE_ENV === "production") {
      logger.warn(
        "USE_QUEUE is not set to true — rate limiters, auth codes, and revoked tokens will use in-memory storage (not shared across instances)",
      );
      if (process.env.ENABLE_SCRAPER !== "false") {
        startScheduler();
        logger.info(
          "In-process scheduler started (set USE_QUEUE=true for full production mode)",
        );
      }
      if (process.env.GEMINI_API_KEY) {
        startTitleClassifierScheduler();
      }
    } else if (process.env.ENABLE_SCRAPER !== "false") {
      startScheduler();
      logger.info(
        "In-process scheduler started (set USE_QUEUE=true for production)",
      );
      if (process.env.GEMINI_API_KEY) {
        startTitleClassifierScheduler();
      }
    } else if (process.env.GEMINI_API_KEY) {
      startTitleClassifierScheduler();
    }

    logger.info({ port: PORT }, "Server starting");

    Bun.serve({
      port: PORT,
      fetch: app.fetch,
      maxRequestBodySize: 1_000_000,
    });

    logger.info({ port: PORT }, "Server running");
  } catch (error) {
    logger.error({ error }, "Failed to start server");
    process.exit(1);
  }
}

async function shutdown() {
  if (shutdownPromise) {
    return shutdownPromise;
  }

  shutdownPromise = (async () => {
    logger.info("Shutting down...");
    signalRedditShutdown();

    if (!USE_QUEUE) {
      stopScheduler();
    }

    const workers = (globalThis as Record<string, unknown>).__workers as
      | { close: () => Promise<void> }[]
      | undefined;
    if (workers) {
      await Promise.all(workers.map((w) => w.close()));
      logger.info("Workers closed");
    }

    if (process.env.GEMINI_API_KEY && !USE_QUEUE) {
      stopTitleClassifierScheduler();
    }

    await shutdownAnalytics();
    await prisma.$disconnect();
    process.exit(0);
  })().catch(async (error) => {
    logger.error({ error }, "Shutdown failed");
    await shutdownAnalytics().catch(() => undefined);
    await prisma.$disconnect().catch(() => undefined);
    process.exit(1);
  });

  return shutdownPromise;
}

process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);

main();

