import { getRedisConnection, shouldUseRedisCache } from "./redis";
import logger from "./logger";

const USE_REDIS_CACHE = shouldUseRedisCache();
const LOCAL_CACHE_MAX_KEYS = Math.max(
  200,
  parseInt(process.env.LOCAL_CACHE_MAX_KEYS || "1200", 10) || 1200,
);

interface LocalCacheEntry {
  value: string;
  expiresAt: number;
}

const localCache = new Map<string, LocalCacheEntry>();

function getPrefixedKey(key: string): string {
  return `cache:${key}`;
}

function pruneLocalCache() {
  if (localCache.size <= LOCAL_CACHE_MAX_KEYS) {
    return;
  }

  const now = Date.now();
  for (const [key, entry] of localCache.entries()) {
    if (entry.expiresAt <= now) {
      localCache.delete(key);
    }
    if (localCache.size <= LOCAL_CACHE_MAX_KEYS) {
      return;
    }
  }

  while (localCache.size > LOCAL_CACHE_MAX_KEYS) {
    const oldestKey = localCache.keys().next().value as string | undefined;
    if (!oldestKey) {
      break;
    }
    localCache.delete(oldestKey);
  }
}

function localCacheGet<T>(key: string): T | null {
  const prefixedKey = getPrefixedKey(key);
  const entry = localCache.get(prefixedKey);
  if (!entry) {
    return null;
  }

  if (entry.expiresAt <= Date.now()) {
    localCache.delete(prefixedKey);
    return null;
  }

  try {
    return JSON.parse(entry.value) as T;
  } catch {
    localCache.delete(prefixedKey);
    return null;
  }
}

function localCacheSet(key: string, data: unknown, ttlSeconds: number) {
  const prefixedKey = getPrefixedKey(key);
  const ttlMs = Math.max(1, ttlSeconds) * 1000;
  localCache.set(prefixedKey, {
    value: JSON.stringify(data),
    expiresAt: Date.now() + ttlMs,
  });
  pruneLocalCache();
}

function localCacheInvalidate(key: string) {
  localCache.delete(getPrefixedKey(key));
}

function localCacheInvalidatePattern(pattern: string) {
  const escapedPattern = pattern.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const wildcardRegex = new RegExp(
    `^${getPrefixedKey("").replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}${escapedPattern.replace(/\\\*/g, ".*")}$`,
  );

  for (const cacheKey of localCache.keys()) {
    if (wildcardRegex.test(cacheKey)) {
      localCache.delete(cacheKey);
    }
  }
}

export async function cacheGet<T>(key: string): Promise<T | null> {
  const localValue = localCacheGet<T>(key);
  if (localValue !== null) {
    return localValue;
  }

  if (!USE_REDIS_CACHE) {
    return null;
  }

  try {
    const redis = getRedisConnection();
    const cached = await redis.get(getPrefixedKey(key));
    if (cached) {
      const parsed = JSON.parse(cached) as T;
      const ttlSeconds = await redis.ttl(getPrefixedKey(key));
      if (ttlSeconds > 0) {
        localCacheSet(key, parsed, ttlSeconds);
      }
      return parsed;
    }
  } catch (err) {
    logger.warn({ err, key }, "Cache get failed");
  }

  return null;
}

export async function cacheSet(
  key: string,
  data: unknown,
  ttlSeconds: number = 60,
): Promise<void> {
  localCacheSet(key, data, ttlSeconds);

  if (!USE_REDIS_CACHE) return;

  try {
    const redis = getRedisConnection();
    await redis.set(
      getPrefixedKey(key),
      JSON.stringify(data),
      "EX",
      ttlSeconds,
    );
  } catch (err) {
    logger.warn({ err, key }, "Cache set failed");
  }
}

export async function cacheInvalidate(key: string): Promise<void> {
  localCacheInvalidate(key);
  if (!USE_REDIS_CACHE) return;

  try {
    const redis = getRedisConnection();
    await redis.del(getPrefixedKey(key));
  } catch (err) {
    logger.warn({ err, key }, "Cache invalidate failed");
  }
}

export async function cacheInvalidatePattern(pattern: string): Promise<void> {
  localCacheInvalidatePattern(pattern);
  if (!USE_REDIS_CACHE) return;

  try {
    const redis = getRedisConnection();
    const keys = await redis.keys(getPrefixedKey(pattern));
    if (keys.length > 0) {
      await redis.del(...keys);
    }
  } catch (err) {
    logger.warn({ err, pattern }, "Cache invalidate pattern failed");
  }
}

import type { Context } from "hono";

interface PublicCachePolicy {
  maxAge: number;
  staleWhileRevalidate?: number;
  staleIfError?: number;
  sMaxAge?: number;
}

function clampDirective(value: number | undefined): number | null {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return null;
  }

  return Math.max(0, Math.floor(value));
}

export function setPublicCacheHeaders(
  c: Context,
  policy: PublicCachePolicy,
): void {
  const directives = [`public`, `max-age=${Math.max(0, Math.floor(policy.maxAge))}`];
  const sMaxAge = clampDirective(policy.sMaxAge);
  const staleWhileRevalidate = clampDirective(policy.staleWhileRevalidate);
  const staleIfError = clampDirective(policy.staleIfError);

  if (sMaxAge !== null) {
    directives.push(`s-maxage=${sMaxAge}`);
  }

  if (staleWhileRevalidate !== null) {
    directives.push(`stale-while-revalidate=${staleWhileRevalidate}`);
  }

  if (staleIfError !== null) {
    directives.push(`stale-if-error=${staleIfError}`);
  }

  c.header("Cache-Control", directives.join(", "));
}

export function setNoStoreHeaders(c: Context): void {
  c.header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0");
  c.header("Pragma", "no-cache");
}

export function preferModernImageUrl(
  url: string | null | undefined,
): string | null {
  if (!url) {
    return null;
  }

  try {
    const parsed = new URL(url);
    const host = parsed.hostname.toLowerCase();

    const modernPath = parsed.pathname.toLowerCase();
    if (modernPath.endsWith(".avif") || modernPath.endsWith(".webp")) {
      return parsed.toString();
    }

    // Reddit preview hosts support query-based format switching.
    const canSwitchByQuery =
      host === "preview.redd.it" ||
      host === "external-preview.redd.it" ||
      host.endsWith(".redditmedia.com");

    if (canSwitchByQuery && parsed.searchParams.has("format")) {
      const format = (parsed.searchParams.get("format") || "").toLowerCase();
      if (format !== "avif" && format !== "webp") {
        parsed.searchParams.set("format", "webp");
        return parsed.toString();
      }
    }

    return parsed.toString();
  } catch {
    return url;
  }
}

export default {
  preferModernImageUrl,
};

import jwt from "jsonwebtoken";
import logger from "./logger";
import { TOKEN_LIFETIMES } from "../config/constants";

const JWT_SECRET = process.env.JWT_SECRET;
const REFRESH_SECRET = process.env.REFRESH_SECRET;

if (process.env.NODE_ENV === "production") {
  if (!JWT_SECRET) {
    logger.fatal("JWT_SECRET environment variable is required in production");
    process.exit(1);
  }
  if (!REFRESH_SECRET) {
    logger.fatal(
      "REFRESH_SECRET environment variable is required in production (must differ from JWT_SECRET)",
    );
    process.exit(1);
  }
} else {
  if (!JWT_SECRET) {
    logger.warn(
      "JWT_SECRET not set — using insecure default. DO NOT use this in production.",
    );
  }
  if (!REFRESH_SECRET) {
    logger.warn(
      "REFRESH_SECRET not set — using insecure default. DO NOT use this in production.",
    );
  }
}

const SECRET = JWT_SECRET || "savekaro-dev-secret-INSECURE";
const REFRESH = REFRESH_SECRET || "savekaro-dev-refresh-INSECURE";

const ACCESS_TOKEN_EXPIRES_IN = TOKEN_LIFETIMES.ACCESS_TOKEN;
const REFRESH_TOKEN_EXPIRES_IN = TOKEN_LIFETIMES.REFRESH_TOKEN;

export interface TokenPayload {
  userId: string;
  email: string;
  name?: string | null;
  avatarUrl?: string | null;
  isAdmin?: boolean;
  type?: "access" | "refresh";
}


export function generateAccessToken(payload: {
  userId: string;
  email: string;
  name?: string | null;
  avatarUrl?: string | null;
  isAdmin?: boolean;
}): string {
  return jwt.sign({ ...payload, type: "access" }, SECRET, {
    expiresIn: ACCESS_TOKEN_EXPIRES_IN,
  });
}

export function verifyAccessToken(token: string): TokenPayload | null {
  try {
    const decoded = jwt.verify(token, SECRET) as TokenPayload;
    if (decoded.type && decoded.type !== "access") return null;
    return decoded;
  } catch {
    return null;
  }
}


export function generateRefreshToken(payload: {
  userId: string;
  email: string;
}): string {
  return jwt.sign({ ...payload, type: "refresh" }, REFRESH, {
    expiresIn: REFRESH_TOKEN_EXPIRES_IN,
  });
}

export function verifyRefreshToken(token: string): TokenPayload | null {
  try {
    const decoded = jwt.verify(token, REFRESH) as TokenPayload;
    if (decoded.type && decoded.type !== "refresh") return null;
    return decoded;
  } catch {
    return null;
  }
}

