export function checkOwnership(
  resourceUserId: string | null,
  currentUserId: string | null,
): boolean {
  if (!resourceUserId || !currentUserId) {
    return false;
  }
  return resourceUserId === currentUserId;
}

export function checkOwnershipOrAdmin(
  resourceUserId: string | null,
  currentUserId: string | null,
  isAdmin: boolean = false,
): boolean {
  if (isAdmin) {
    return true;
  }
  return checkOwnership(resourceUserId, currentUserId);
}

export function validateOwnership(
  resourceUserId: string | null,
  currentUserId: string | null,
): { success: false; error: string } | null {
  if (!checkOwnership(resourceUserId, currentUserId)) {
    return { success: false, error: "Not authorized" };
  }
  return null;
}

export function validateOwnershipOrAdmin(
  resourceUserId: string | null,
  currentUserId: string | null,
  isAdmin: boolean = false,
): { success: false; error: string } | null {
  if (!checkOwnershipOrAdmin(resourceUserId, currentUserId, isAdmin)) {
    return { success: false, error: "Not authorized" };
  }
  return null;
}

export interface PaginationParams {
  page: number;
  limit: number;
  skip: number;
}

export interface PaginationResponse {
  total: number;
  page: number;
  limit: number;
  totalPages: number;
}

export function parsePaginationParams(
  pageParam?: string,
  limitParam?: string,
  defaultLimit: number = 20,
  maxLimit: number = 100,
): PaginationParams {
  const page = Math.max(1, parseInt(pageParam || "1", 10) || 1);
  const limit = Math.min(
    maxLimit,
    Math.max(
      1,
      parseInt(limitParam || defaultLimit.toString(), 10) || defaultLimit,
    ),
  );
  const skip = (page - 1) * limit;

  return { page, limit, skip };
}

export function createPaginationResponse(
  total: number,
  page: number,
  limit: number,
): PaginationResponse {
  return {
    total,
    page,
    limit,
    totalPages: Math.ceil(total / limit),
  };
}

export function parsePaginationFromContext(
  c: any,
  defaultLimit: number = 20,
): PaginationParams {
  return parsePaginationParams(
    c.req.query("page"),
    c.req.query("limit"),
    defaultLimit,
    100,
  );
}

