    deal_id: deal.id,
    category_id: deal.categoryId ?? "unknown",
    store: deal.storeKey || deal.store?.trim() || "unknown",
    region: deal.region ?? "unknown",
    source: deal.source ?? "unknown",
    discount_percent: deal.discountPercent ?? null,
  };
}

export type ServerAnalyticsEvent =
  | "auth:login_complete"
  | "deal:submit_complete"
  | "deal:vote_change"
  | "deal:save_change"
  | "deal:merchant_click"
  | "comment:create"
  | "notification:read"
  | "alert:create"
  | "alert:status_change"
  | "alert:delete";

const CONSENT_HEADER = "X-SaveKaro-Analytics-Consent";
const DISTINCT_ID_HEADER = "X-PostHog-Distinct-Id";
const SESSION_ID_HEADER = "X-PostHog-Session-Id";
const WINDOW_ID_HEADER = "X-PostHog-Window-Id";

function cleanAnalyticsId(value: string | undefined): string | undefined {
  if (!value || value.length > 200) return undefined;
  return /^[a-zA-Z0-9._:-]+$/.test(value) ? value : undefined;
}

export function hasAnalyticsConsent(c: Context): boolean {
  return c.req.header(CONSENT_HEADER)?.toLowerCase() === "granted";
}

export function captureServerEvent(
  c: Context,
  event: ServerAnalyticsEvent,
  properties: ServerAnalyticsProperties = {},
  distinctIdOverride?: string,
) {
  if (!client || !hasAnalyticsConsent(c)) return;

  const distinctId =
    cleanAnalyticsId(distinctIdOverride) ||
    cleanAnalyticsId(c.get("userId") || undefined) ||
    cleanAnalyticsId(c.req.header(DISTINCT_ID_HEADER));

  if (!distinctId) return;

  const sessionId = cleanAnalyticsId(c.req.header(SESSION_ID_HEADER));
  const windowId = cleanAnalyticsId(c.req.header(WINDOW_ID_HEADER));

  try {
    client.capture({
      distinctId,
      event,
      properties: {
        ...properties,
        app_environment: process.env.APP_ENV || process.env.NODE_ENV || "unknown",
        service: "savekaro-api",
        request_id: c.get("requestId"),
        $session_id: sessionId,
        $window_id: windowId,
        $geoip_disable: true,
      },
    });
  } catch (error) {
    logger.warn({ error, event }, "PostHog capture failed");
  }
}

export function captureServerException(c: Context, error: unknown) {
  if (!client || !hasAnalyticsConsent(c)) return;

  const distinctId =
    cleanAnalyticsId(c.get("userId") || undefined) ||
    cleanAnalyticsId(c.req.header(DISTINCT_ID_HEADER));
  if (!distinctId) return;

  try {
    client.captureException(error, distinctId, {
      request_id: c.get("requestId"),
      method: c.req.method,
      route: c.req.path,
      $session_id: cleanAnalyticsId(c.req.header(SESSION_ID_HEADER)),
      $geoip_disable: true,
    });
  } catch (captureError) {
    logger.warn({ error: captureError }, "PostHog exception capture failed");
  }
}

export async function shutdownAnalytics() {
  if (!client) return;

  try {
    await client.shutdown(5_000);
  } catch (error) {
    logger.warn({ error }, "PostHog shutdown flush failed");
  }
}

import { normalizeHost } from "./url";

const TRACKING_QUERY_PARAMS = new Set([
  "utm_source",
  "utm_medium",
  "utm_campaign",
  "utm_term",
  "utm_content",
  "utm_id",
  "gclid",
  "fbclid",
  "msclkid",
  "igshid",
  "ref",
  "ref_",
  "source",
  "affid",
  "aff_id",
  "affiliate",
  "affiliate_id",
  "tag",
  "linkcode",
  "camp",
  "creative",
  "creativeasin",
  "ascsubtag",
  "psc",
  "smid",
]);

const TRACKING_QUERY_PARAM_PREFIXES = [
  "utm_",
  "mc_",
  "ga_",
  "pk_",
  "srsltid",
];

const PRODUCT_QUERY_PARAM_ALLOWLIST = new Set([
  "id",
  "pid",
  "sku",
  "model",
  "variant",
  "color",
  "size",
]);



function normalizePathname(pathname: string): string {
  const normalized = pathname.replace(/\/{2,}/g, "/").replace(/\/+$/g, "");
  return normalized || "/";
}

export function normalizeWatchedProductUrl(url: string): string | null {
  try {
    const parsed = new URL(url);
    if (!/^https?:$/i.test(parsed.protocol)) {
      return null;
    }

    const host = parsed.hostname.replace(/^(www|m)\./i, "").toLowerCase();
    let pathname = normalizePathname(parsed.pathname);

    if (pathname === "/" && !parsed.searchParams.size) {
      return null;
    }

    if (/amazon\./i.test(host)) {
      const amazonMatch = pathname.match(
        /\/(?:gp\/product|dp|exec\/obidos\/ASIN)\/([A-Z0-9]{10})/i,
      );
      if (amazonMatch) {
        pathname = `/dp/${amazonMatch[1].toUpperCase()}`;
      }
      return `${host}${pathname}`;
    }

    const keptEntries = Array.from(parsed.searchParams.entries())
      .filter(([key, value]) => {
        const normalizedKey = key.trim().toLowerCase();
        if (!normalizedKey || !value.trim()) return false;
        if (TRACKING_QUERY_PARAMS.has(normalizedKey)) return false;
        if (
          TRACKING_QUERY_PARAM_PREFIXES.some((prefix) =>
            normalizedKey.startsWith(prefix),
          )
        ) {
          return false;
        }
        return PRODUCT_QUERY_PARAM_ALLOWLIST.has(normalizedKey);
      })
      .map(
        ([key, value]) =>
          [key.trim().toLowerCase(), value.trim().toLowerCase()] as const,
      )
      .sort(([a], [b]) => a.localeCompare(b));

    const normalizedQuery = keptEntries.length
      ? `?${new URLSearchParams(keptEntries as [string, string][]).toString()}`
      : "";

    if (pathname === "/" && !normalizedQuery) {
      return null;
    }

    return `${host}${pathname}${normalizedQuery}`;
  } catch {
    return null;
  }
}

export function buildWatchUrlLabel(url: string): string {
  try {
    const parsed = new URL(url);
    const host = normalizeHost(url) ?? parsed.hostname.toLowerCase();
    const hostLabel = host
      .replace(/\.(com|in|net|org|co|store|shop)$/i, "")
      .replace(/[.-]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();

    const segments = parsed.pathname
      .split("/")
      .map((segment) => segment.trim())
      .filter(Boolean)
      .reverse();

    const rawSegment =
      segments.find(
        (segment) =>
          segment.length > 3 &&
          !["dp", "gp", "product", "products", "item", "items", "p"].includes(
            segment.toLowerCase(),
          ),
      ) ?? "";

    const cleanedSegment = decodeURIComponent(rawSegment)
      .replace(/\.[a-z0-9]{2,5}$/i, "")
      .replace(/[_-]+/g, " ")
      .replace(/[^a-z0-9 ]/gi, " ")
      .replace(/\s+/g, " ")
      .trim();

    const shortLabel = cleanedSegment
      .split(" ")
      .filter((part) => part.length > 1)
      .slice(0, 6)
      .join(" ");

    if (shortLabel) {
      return `${hostLabel} • ${shortLabel}`;
    }

    return `${hostLabel} watchlist`;
  } catch {
    return "Product URL watchlist";
  }
}

