import Redis from "ioredis";
import logger from "./logger";

const CONFIGURED_REDIS_URL = process.env.REDIS_URL?.trim() || null;
const REDIS_URL = CONFIGURED_REDIS_URL || "redis://localhost:6379";
const USE_QUEUE = process.env.USE_QUEUE === "true";
const USE_REDIS_CACHE = process.env.USE_REDIS_CACHE !== "false";

let _connection: Redis | null = null;

export function getRedisConnection(): Redis {
  if (!_connection) {
    _connection = new Redis(REDIS_URL, {
      maxRetriesPerRequest: null, // Required for BullMQ
      enableReadyCheck: false,
    });

    _connection.on("connect", () => {
      logger.info("Redis connected");
    });

    _connection.on("error", (err) => {
      logger.error({ error: err }, "Redis connection error");
    });
  }
  return _connection;
}

export function isRedisConfigured(): boolean {
  return Boolean(CONFIGURED_REDIS_URL);
}

export function shouldUseRedisCache(): boolean {
  return USE_REDIS_CACHE && isRedisConfigured();
}

export const redisConnection: Redis = USE_QUEUE
  ? getRedisConnection()
  : (null as unknown as Redis);

export async function isRedisHealthy(): Promise<boolean> {
  try {
    if (!_connection) return false;
    const result = await _connection.ping();
    return result === "PONG";
  } catch {
    return false;
  }
}

export default redisConnection;

export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  details?: any;
}

export interface PaginatedApiResponse<T = any> extends ApiResponse<T[]> {
  pagination?: {
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  };
  unreadCount?: number; // For notifications endpoint compatibility
}

export function successResponse<T>(data: T): ApiResponse<T> {
  return { success: true, data };
}

export function paginatedSuccessResponse<T>(
  data: T[],
  pagination: {
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  },
  unreadCount?: number,
): PaginatedApiResponse<T> {
  const response: PaginatedApiResponse<T> = {
    success: true,
    data,
    pagination,
  };

  if (unreadCount !== undefined) {
    response.unreadCount = unreadCount;
  }

  return response;
}

export function errorResponse(error: string, details?: any): ApiResponse {
  const response: ApiResponse = { success: false, error };
  if (details) {
    response.details = details;
  }
  return response;
}

export function notFoundResponse(resource: string): ApiResponse {
  return errorResponse(`${resource} not found`);
}

export function unauthorizedResponse(
  message: string = "Not authorized",
): ApiResponse {
  return errorResponse(message);
}

export function authRequiredResponse(): ApiResponse {
  return errorResponse("Authentication required");
}

export function validationErrorResponse(
  message: string,
  details?: any,
): ApiResponse {
  return errorResponse(message, details);
}

export function stripHtml(input: string): string {
  return input
    .replace(/<[^>]*>?/g, "")
    .replace(/&[a-z]+;/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function escapeHtml(input: string): string {
  return input
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

const STORE_KEY_ALIASES: Array<{ key: string; aliases: string[] }> = [
  { key: "amazon", aliases: ["amazon", "amzn"] },
  { key: "myntra", aliases: ["myntra", "myntr"] },
  { key: "ajio", aliases: ["ajio", "ajiio"] },
  { key: "nykaa", aliases: ["nykaa"] },
  { key: "croma", aliases: ["croma"] },
  { key: "tata", aliases: ["tata", "tatacliq", "tataneu"] },
  { key: "flipkart", aliases: ["flipkart"] },
  { key: "meesho", aliases: ["meesho"] },
  { key: "bestbuy", aliases: ["bestbuy"] },
  { key: "walmart", aliases: ["walmart"] },
  { key: "costco", aliases: ["costco"] },
  { key: "canadiantire", aliases: ["canadiantire"] },
  { key: "thesource", aliases: ["thesource"] },
  { key: "shoppersdrugmart", aliases: ["shoppersdrugmart"] },
  { key: "londondrugs", aliases: ["londondrugs"] },
];

const MULTI_PART_TLD_PREFIXES = new Set([
  "ac",
  "co",
  "com",
  "edu",
  "gov",
  "net",
  "org",
]);

function compactStoreToken(value: string | null | undefined): string | null {
  const normalized = (value || "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "");

  return normalized || null;
}

function resolveAliasStoreKey(token: string | null): string | null {
  if (!token) {
    return null;
  }

  const aliasMatch = STORE_KEY_ALIASES.find((entry) =>
    entry.aliases.some((alias) => token.includes(alias)),
  );

  return aliasMatch?.key ?? token;
}

function extractRegistrableDomainToken(hostname: string): string | null {
  const parts = hostname
    .replace(/^(www|m)\./i, "")
    .toLowerCase()
    .split(".")
    .filter(Boolean);

  if (parts.length === 0) {
    return null;
  }

  if (parts.length === 1) {
    return compactStoreToken(parts[0]);
  }

  const topLevel = parts[parts.length - 1];
  const secondLevel = parts[parts.length - 2];

  if (
    topLevel.length === 2 &&
    MULTI_PART_TLD_PREFIXES.has(secondLevel) &&
    parts.length >= 3
  ) {
    return compactStoreToken(parts[parts.length - 3]);
  }

  return compactStoreToken(secondLevel);
}

export function getStoreKeyFromFilter(
  store: string | null | undefined,
): string | null {
  return resolveAliasStoreKey(compactStoreToken(store));
}

export function getCanonicalStoreKey(params: {
  store?: string | null;
  productUrl?: string | null;
}): string | null {
  const fromStore = getStoreKeyFromFilter(params.store);
  if (fromStore) {
    return fromStore;
  }

  if (!params.productUrl) {
    return null;
  }

  try {
    const hostname = new URL(params.productUrl).hostname;
    const hostToken = extractRegistrableDomainToken(hostname);
    return resolveAliasStoreKey(hostToken);
  } catch {
    return null;
  }
}

/**
 * Extracts and normalizes the hostname from a URL.
 * Strips `www.` and `m.` prefixes and lowercases the result.
 */
export function normalizeHost(url: string): string | null {
  try {
    return new URL(url).hostname.replace(/^(www|m)\./i, "").toLowerCase();
  } catch {
    return null;
  }
}

import { Context, Next } from "hono";
import { verifyAccessToken, TokenPayload } from "../lib/jwt";
import prisma from "../lib/prisma";
import { AUTH_CACHE } from "../config/constants";

declare module "hono" {
  interface ContextVariableMap {
    user: {
      id: string;
      email: string;
      name: string | null;
      avatarUrl: string | null;
      isAdmin: boolean;
    } | null;
    userId: string | null;
  }
}

type AuthUser = NonNullable<Context["var"]["user"]>;

interface CachedAuthUser {
  user: AuthUser | null;
  validatedAt: number;
}

const AUTH_REVALIDATION_MS = Math.max(
  30_000,
  parseInt(
    process.env.AUTH_REVALIDATION_MS || `${AUTH_CACHE.USER_REVALIDATION_MS}`,
    10,
  ) || AUTH_CACHE.USER_REVALIDATION_MS,
);

const AUTH_CACHE_MAX_USERS = Math.max(
  500,
  parseInt(
    process.env.AUTH_CACHE_MAX_USERS || `${AUTH_CACHE.MAX_USERS}`,
    10,
  ) || AUTH_CACHE.MAX_USERS,
);

const authUserCache = new Map<string, CachedAuthUser>();
const authRevalidationInFlight = new Map<string, Promise<AuthUser | null>>();

function setAuthContext(c: Context, user: AuthUser | null) {
  c.set("user", user);
  c.set("userId", user?.id || null);
}

function setCachedAuthUser(userId: string, user: AuthUser | null) {
  if (!authUserCache.has(userId) && authUserCache.size >= AUTH_CACHE_MAX_USERS) {
    const oldestKey = authUserCache.keys().next().value as string | undefined;
    if (oldestKey) {
      authUserCache.delete(oldestKey);
    }
  }
  authUserCache.set(userId, { user, validatedAt: Date.now() });
}

function getTokenUser(payload: TokenPayload): AuthUser | null {
  if (typeof payload.isAdmin !== "boolean") {
    return null;
  }

  return {
    id: payload.userId,
    email: payload.email,
    name: payload.name ?? null,
    avatarUrl: payload.avatarUrl ?? null,
    isAdmin: payload.isAdmin,
  };
}

async function fetchUserFromDb(userId: string): Promise<AuthUser | null> {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      id: true,
      email: true,
      name: true,
      avatarUrl: true,
      isAdmin: true,
    },
  });

  return user ?? null;
}

function revalidateUser(userId: string): Promise<AuthUser | null> {
  const existing = authRevalidationInFlight.get(userId);
  if (existing) {
    return existing;
  }

  const promise = fetchUserFromDb(userId)
    .then((user) => {
      setCachedAuthUser(userId, user);
      return user;
    })
    .catch(() => {
      return null;
    })
    .finally(() => {
      authRevalidationInFlight.delete(userId);
    });

  authRevalidationInFlight.set(userId, promise);
  return promise;
}

export async function authMiddleware(c: Context, next: Next) {
  const authHeader = c.req.header("Authorization");

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    c.set("user", null);
    c.set("userId", null);
    return next();
  }

  const token = authHeader.substring(7);
  const payload = verifyAccessToken(token);

  if (!payload) {
    c.set("user", null);
    c.set("userId", null);
    return next();
  }

  const cacheEntry = authUserCache.get(payload.userId);
  const now = Date.now();
  const isCacheFresh =
    cacheEntry !== undefined &&
    now - cacheEntry.validatedAt < AUTH_REVALIDATION_MS;

  if (isCacheFresh) {
    setAuthContext(c, cacheEntry.user);
    return next();
  }

  const tokenUser = getTokenUser(payload);

  // Legacy tokens without full user claims still require a synchronous DB check.
  if (!tokenUser) {
    const dbUser = await revalidateUser(payload.userId);
    setAuthContext(c, dbUser);
    return next();
  }

  // Cold cache: validate once synchronously, then reuse cached user for subsequent requests.
  if (!cacheEntry) {
    try {
      const dbUser = await fetchUserFromDb(payload.userId);
      setCachedAuthUser(payload.userId, dbUser);
      setAuthContext(c, dbUser);
    } catch {
      // DB transient failure fallback: use signed token claims for this request.
      setAuthContext(c, tokenUser);
    }
    return next();
  }

  // Stale cache: use cached user immediately for low latency and refresh in background.
  setAuthContext(c, cacheEntry.user);

  void revalidateUser(payload.userId);

  return next();
}

export async function requireAuth(c: Context, next: Next) {
  const user = c.get("user");

  if (!user) {
    return c.json(
      {
        success: false,
        error: "Authentication required",
      },
      401,
    );
  }

  return next();
}

import { Hono } from "hono";
import prisma from "../lib/prisma";
import { requireAuth } from "../middleware/auth";
import { validate, getValidated } from "../middleware/validate";
import {
  createAlertSchema,
  updateAlertSchema,
  CreateAlertInput,
  UpdateAlertInput,
} from "../schemas";
import { successResponse, errorResponse, notFoundResponse } from "../lib/responses";
import { validateOwnership } from "../lib/ownership";
import { PRICE_ALERT_LIMITS } from "../config/constants";
import {
  buildWatchUrlLabel,
  normalizeWatchedProductUrl,
} from "../lib/price-alert-watch";
import { captureServerEvent } from "../lib/posthog";

const alerts = new Hono();

const MAX_ALERTS_PER_USER = PRICE_ALERT_LIMITS.MAX_ALERTS_PER_USER;

alerts.get("/", requireAuth, async (c) => {
  const userId = c.get("userId")!;

  const userAlerts = await prisma.priceAlert.findMany({
    where: { userId },
    orderBy: { createdAt: "desc" },
  });

  return c.json(successResponse(userAlerts));
});

alerts.post("/", requireAuth, validate(createAlertSchema), async (c) => {
  const userId = c.get("userId")!;
  const data = getValidated<CreateAlertInput>(c);
  const mode = data.mode ?? "KEYWORD";

  const count = await prisma.priceAlert.count({ where: { userId } });
  if (count >= MAX_ALERTS_PER_USER) {
    return c.json(
      errorResponse(
        `You can have at most ${MAX_ALERTS_PER_USER} alerts. Delete one to create a new one.`
      ),
      400,
    );
  }

  const watchUrl = mode === "URL" ? data.watchUrl?.trim() ?? null : null;
  const watchUrlNormalized = watchUrl
    ? normalizeWatchedProductUrl(watchUrl)
    : null;

  if (mode === "URL" && !watchUrlNormalized) {
    return c.json(
      errorResponse("Please enter a specific HTTPS product URL, not a homepage."),
      400,
    );
  }

  if (watchUrlNormalized) {
    const existingWatchAlert = await prisma.priceAlert.findFirst({
      where: {
        userId,
        watchUrlNormalized,
      },
      select: { id: true },
    });

    if (existingWatchAlert) {
      return c.json(
        errorResponse("You are already tracking this product URL."),
        409,
      );
    }
  }

  const alert = await prisma.priceAlert.create({
    data: {
      userId,
      mode,
      keywords:
        mode === "URL"
          ? buildWatchUrlLabel(watchUrl!)
          : data.keywords!.trim(),
      watchUrl,
      watchUrlNormalized,
      maxPrice: data.maxPrice ?? null,
      categoryId: mode === "URL" ? null : (data.categoryId ?? null),
      region: data.region ?? null,
    },
  });

  captureServerEvent(c, "alert:create", {
    alert_id: alert.id,
    alert_mode: mode,
    region: alert.region,
    has_max_price: alert.maxPrice !== null,
    has_category: alert.categoryId !== null,
  });

  return c.json(successResponse(alert), 201);
});

alerts.put("/:id", requireAuth, validate(updateAlertSchema), async (c) => {
  const userId = c.get("userId")!;
  const id = c.req.param("id");
  const data = getValidated<UpdateAlertInput>(c);

  const existing = await prisma.priceAlert.findUnique({ where: { id } });

  if (!existing) {
    return c.json(notFoundResponse("Alert"), 404);
  }

  const ownershipError = validateOwnership(existing.userId, userId);
  if (ownershipError) {
    return c.json(ownershipError, 403);
  }

  const nextMode = data.mode ?? existing.mode;
  const nextWatchUrl =
    data.watchUrl !== undefined ? data.watchUrl?.trim() ?? null : existing.watchUrl;
  const nextWatchUrlNormalized =
    nextMode === "URL" && nextWatchUrl
      ? normalizeWatchedProductUrl(nextWatchUrl)
      : null;

  if (nextMode === "URL" && !nextWatchUrlNormalized) {
    return c.json(
      errorResponse("Please enter a specific HTTPS product URL, not a homepage."),
      400,
    );
  }

  if (nextWatchUrlNormalized) {
    const conflictingAlert = await prisma.priceAlert.findFirst({
      where: {
        userId,
        id: { not: id },
        watchUrlNormalized: nextWatchUrlNormalized,
      },
      select: { id: true },
    });

    if (conflictingAlert) {
      return c.json(
        errorResponse("You are already tracking this product URL."),
        409,
      );
    }
  }

  const nextKeywords =
    nextMode === "URL"
      ? buildWatchUrlLabel(nextWatchUrl!)
      : data.keywords?.trim() ?? existing.keywords;

  const updated = await prisma.priceAlert.update({
    where: { id },
    data: {
      mode: nextMode,
      keywords: nextKeywords,
      watchUrl: nextMode === "URL" ? nextWatchUrl : null,
      watchUrlNormalized: nextMode === "URL" ? nextWatchUrlNormalized : null,
      maxPrice:
        data.maxPrice !== undefined ? (data.maxPrice ?? null) : undefined,
      categoryId:
        nextMode === "URL"
          ? null
          : data.categoryId !== undefined
            ? (data.categoryId ?? null)
            : undefined,
      region: data.region !== undefined ? (data.region ?? null) : undefined,
    },
  });

  return c.json(successResponse(updated));
});

alerts.put("/:id/toggle", requireAuth, async (c) => {
  const userId = c.get("userId")!;
  const id = c.req.param("id");

  const existing = await prisma.priceAlert.findUnique({ where: { id } });

  if (!existing) {
    return c.json(notFoundResponse("Alert"), 404);
  }

  const ownershipError = validateOwnership(existing.userId, userId);
  if (ownershipError) {
    return c.json(ownershipError, 403);
  }

  const updated = await prisma.priceAlert.update({
    where: { id },
    data: { isActive: !existing.isActive },
  });

  captureServerEvent(c, "alert:status_change", {
    alert_id: updated.id,
    active: updated.isActive,
    alert_mode: updated.mode,
  });

  return c.json(successResponse(updated));
});

alerts.delete("/:id", requireAuth, async (c) => {
  const userId = c.get("userId")!;
  const id = c.req.param("id");

  const existing = await prisma.priceAlert.findUnique({ where: { id } });

  if (!existing) {
    return c.json(notFoundResponse("Alert"), 404);
  }

  const ownershipError = validateOwnership(existing.userId, userId);
  if (ownershipError) {
    return c.json(ownershipError, 403);
  }

  await prisma.priceAlert.delete({ where: { id } });

  captureServerEvent(c, "alert:delete", {
    alert_id: id,
    alert_mode: existing.mode,
  });

  return c.json(successResponse({ message: "Alert deleted" }));
});

