interface AuthCodePayload {
  userId: string;
  email: string;
  name?: string | null;
  avatarUrl?: string | null;
  isAdmin?: boolean;
  isNewUser?: boolean;
}

const USE_REDIS = process.env.USE_QUEUE === "true";

const _authCodesMap = new Map<
  string,
  AuthCodePayload & { expiresAt: number }
>();
const _revokedTokensMap = new Map<string, number>();

// Clean up expired in-memory entries periodically
setInterval(() => {
  const now = Date.now();
  for (const [code, data] of _authCodesMap) {
    if (data.expiresAt < now) _authCodesMap.delete(code);
  }
  for (const [token, expiresAt] of _revokedTokensMap) {
    if (expiresAt < now) _revokedTokensMap.delete(token);
  }
}, 60 * 1000);

async function storeAuthCode(
  code: string,
  data: AuthCodePayload,
): Promise<void> {
  if (USE_REDIS) {
    try {
      const redis = getRedisConnection();
      await redis.set(
        `authcode:${code}`,
        JSON.stringify(data),
        "EX",
        60, // 1 minute TTL
      );
      return;
    } catch (err) {
      logger.warn({ err }, "Redis auth code store failed, using in-memory");
    }
  }
  _authCodesMap.set(code, { ...data, expiresAt: Date.now() + 60 * 1000 });
}

async function consumeAuthCode(code: string): Promise<AuthCodePayload | null> {
  if (USE_REDIS) {
    try {
      const redis = getRedisConnection();
      const raw = await redis.get(`authcode:${code}`);
      if (!raw) return null;
      await redis.del(`authcode:${code}`); // one-time use
      return JSON.parse(raw);
    } catch (err) {
      logger.warn({ err }, "Redis auth code consume failed, trying in-memory");
    }
  }
  const data = _authCodesMap.get(code);
  if (!data) return null;
  _authCodesMap.delete(code);
  if (data.expiresAt < Date.now()) return null;
  return {
    userId: data.userId,
    email: data.email,
    name: data.name,
    avatarUrl: data.avatarUrl,
    isAdmin: data.isAdmin,
    isNewUser: data.isNewUser,
  };
}

async function revokeRefreshToken(token: string): Promise<void> {
  if (USE_REDIS) {
    try {
      const redis = getRedisConnection();
      await redis.set(
        `revoked:${token}`,
        "1",
        "EX",
        7 * 24 * 60 * 60, // 7 days — matches refresh token lifetime
      );
      return;
    } catch (err) {
      logger.warn({ err }, "Redis revoke failed, using in-memory");
    }
  }
  _revokedTokensMap.set(token, Date.now() + 7 * 24 * 60 * 60 * 1000);
}

async function isTokenRevoked(token: string): Promise<boolean> {
  if (USE_REDIS) {
    try {
      const redis = getRedisConnection();
      const result = await redis.get(`revoked:${token}`);
      return result !== null;
    } catch (err) {
      logger.warn({ err }, "Redis revoke check failed, checking in-memory");
    }
  }
  const expiresAt = _revokedTokensMap.get(token);
  if (!expiresAt) return false;
  if (expiresAt < Date.now()) {
    _revokedTokensMap.delete(token);
    return false;
  }
  return true;
}

// Helper to set refresh token cookie
function setRefreshCookie(c: Context, token: string) {
  const maxAge = 7 * 24 * 60 * 60; // 7 days in seconds
  // Use SameSite=None + Secure only in production (cross-domain).
  // For localhost HTTP development, use SameSite=Lax + Secure=false
  // because localhost ports (3001 and 5173) are considered the same site.
  // We omit `domain` to make it a pure Host-Only cookie on the API domain.
  setCookie(c, "refresh_token", token, {
    path: "/api/auth",
    maxAge,
    expires: new Date(Date.now() + maxAge * 1000), // Explicit expires prevents session-cookie fallback drops
    httpOnly: true,
    secure: IS_PRODUCTION,
    sameSite: IS_PRODUCTION ? "None" : "Lax",
  });
}

// Helper to clear refresh token cookie
function clearRefreshCookie(c: Context) {
  deleteCookie(c, "refresh_token", {
    path: "/api/auth",
    secure: IS_PRODUCTION,
    sameSite: IS_PRODUCTION ? "None" : "Lax",
  });
}


