import { getRedis } from "./redis.js";
import { spectatorsKey } from "./keys.js";
import { prisma } from "./prisma.js";
import { withDbRetry } from "./prisma-retry.js";
import {
  buildRoomSnapshot,
  getRedisBidders,
  initRoomRedisState,
  loadParticipants,
  loadRoomMeta,
} from "./room-state.js";
import { markPresent, broadcastPresence } from "./presence.js";
import { type Ack, type LiveRoomState, ServerEvent } from "@auction/shared";

export async function handleJoinRoom(
  io: Server,
  socket: Socket,
  payload: unknown,
  ack: Ack<LiveRoomState>,
): Promise<void> {
  const user = socket.data.user;
  if (!user) {
    ack({ ok: false, error: { message: "not authenticated" } });
    return;
  }

  const roomId =
    typeof payload === "object" &&
    payload &&
    "roomId" in payload &&
    typeof (payload as { roomId?: unknown }).roomId === "string"
      ? (payload as { roomId: string }).roomId
      : null;

  if (!roomId) {
    ack({ ok: false, error: { message: "roomId is required" } });
    return;
  }

  const meta = await loadRoomMeta(roomId);
  if (!meta) {
    ack({ ok: false, error: { message: "room not found" } });
    return;
  }

  const participantRow = await withDbRetry(() =>
    prisma.roomParticipant.findUnique({
      where: { roomId_userId: { roomId, userId: user.id } },
      select: { id: true },
    }),
  );

  const isAuctioneer = meta.auctioneerId === user.id;
  let isSpectator = false;

  if (meta.status === "AUCTION" && !isAuctioneer) {
    if (!participantRow) {
      // Join as spectator
      isSpectator = true;
    }
  } else if (meta.status === "LOBBY" && !isAuctioneer && !participantRow) {
    ack({
      ok: false,
      error: {
        message:
          "You are not a participant in this room. Join the lobby first.",
        reason: "ROOM_NOT_JOINABLE",
      },
    });
    return;
  }

  const redis = getRedis();

  // Always ensure bidders are synced to Redis before building snapshot,
  // regardless of whether the joining user is a spectator or not.
  const redisBidders = await getRedisBidders(roomId);
  if (redisBidders.length === 0) {
    const participants = await loadParticipants(roomId, meta.perRoomBudget);
    if (participants.length > 0) {
      await initRoomRedisState(meta, participants);
    }
  }

  if (isSpectator) {
    // Track spectator in Redis
    await redis.sadd(spectatorsKey(roomId), user.id);
  }

  const snapshot = await buildRoomSnapshot(roomId);
  if (!snapshot) {
    ack({ ok: false, error: { message: "room snapshot unavailable" } });
    return;
  }

  if (socket.data.roomId && socket.data.roomId !== roomId) {
    socket.leave(socket.data.roomId);
    // Remove from old room's spectators if applicable
    if (socket.data.isSpectator) {
      await redis.srem(spectatorsKey(socket.data.roomId), user.id);
    }
  }
  socket.data.roomId = roomId;
  socket.data.isSpectator = isSpectator;
  socket.join(roomId);

  if (isSpectator) {
    // Broadcast updated spectator count to room after joining
    const spectatorIds = await redis.smembers(spectatorsKey(roomId));
    io.to(roomId).emit(ServerEvent.SPECTATORS_CHANGED, { spectatorIds });
  }

  await markPresent(roomId, user.id);
  await broadcastPresence(io, roomId);

  if (!isSpectator) {
    io.to(roomId).emit(ServerEvent.PARTICIPANT_UPDATE, {
      participant:
        snapshot.bidders.find((b) => b.userId === user.id) ?? {
          userId: user.id,
          name: user.name,
          role: user.role,
          budget: 0,
          reserved: 0,
          available: 0,
          spent: 0,
        },
    });
  }

  ack({ ok: true, data: snapshot });
}

export const roomKey = (roomId: string): string => `auction:room:${roomId}`;
export const biddersKey = (roomId: string): string =>
  `${roomKey(roomId)}:bidders`;
export const itemKey = (roomId: string, itemId: string): string =>
  `${roomKey(roomId)}:item:${itemId}`;
export const resolvedListKey = (roomId: string): string =>
  `${roomKey(roomId)}:resolved`;
export const presenceKey = (roomId: string): string =>
  `${roomKey(roomId)}:presence`;
export const spectatorsKey = (roomId: string): string =>
  `${roomKey(roomId)}:spectators`;

import type { Server, Socket } from "socket.io";

import { getRedis } from "./redis.js";
import { presenceKey } from "./keys.js";
import { ServerEvent } from "@auction/shared";

const PRESENCE_TTL_SECONDS = 60;

export async function markPresent(roomId: string, userId: string): Promise<void> {
  const redis = getRedis();
  await redis.sadd(presenceKey(roomId), userId);
  await redis.expire(presenceKey(roomId), PRESENCE_TTL_SECONDS);
}

export async function markAbsent(
  roomId: string,
  userId: string,
): Promise<void> {
  const redis = getRedis();
  await redis.srem(presenceKey(roomId), userId);
}

export async function listPresent(roomId: string): Promise<string[]> {
  const redis = getRedis();
  return redis.smembers(presenceKey(roomId));
}

export function broadcastPresence(io: Server, roomId: string): Promise<void> {
  return listPresent(roomId).then((userIds) => {
    io.to(roomId).emit(ServerEvent.PRESENCE, { roomId, userIds });
  });
}

import { PrismaClient } from "@prisma/client";

type RetryableError =
  | { name: string; message: string; code?: string }
  | Error;

const TRANSIENT_ERROR_PATTERNS = [
  "Connection terminated",
  "Connection refused",
  "Connection lost",
  "Can't reach database server",
  "Server has closed the connection",
  "P1001",
  "P1002",
  "P1017",
  "P2028",
  "Timed out",
  "ETIMEDOUT",
  "ECONNRESET",
];

function isTransientError(err: unknown): boolean {
  const e = err as RetryableError;
  const name = e?.name ?? "";
  const message = e?.message ?? "";
  const code = (e as { code?: string })?.code ?? "";
  const haystack = `${name} ${message} ${code}`;
  return TRANSIENT_ERROR_PATTERNS.some((p) => haystack.includes(p));
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

const MAX_RETRIES = 3;
const BASE_DELAY_MS = 1000;

export async function withDbRetry<T>(
  fn: () => Promise<T>,
  retries = MAX_RETRIES,
): Promise<T> {
  let lastError: unknown;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      if (isTransientError(err) && attempt < retries) {
        const delay = BASE_DELAY_MS * (attempt + 1);
        console.warn(
          `[prisma-retry] transient DB error on attempt ${attempt + 1}/${retries + 1}, retrying in ${delay}ms:`,
          err instanceof Error ? err.message : err,
        );
        await sleep(delay);
        continue;
      }
      throw err;
    }
  }
  throw lastError;
}

const KEEPALIVE_INTERVAL_MS = 4 * 60 * 1000;

let keepaliveTimer: NodeJS.Timeout | null = null;

export function startKeepalive(client: PrismaClient): void {
  if (keepaliveTimer) return;
  keepaliveTimer = setInterval(() => {
    client
      .$queryRaw`SELECT 1`
      .then(() => {})
      .catch((err) => {
        console.error("[prisma-keepalive] ping failed:", err);
      });
  }, KEEPALIVE_INTERVAL_MS);
  keepaliveTimer.unref?.();
}

export function stopKeepalive(): void {
  if (keepaliveTimer) {
    clearInterval(keepaliveTimer);
    keepaliveTimer = null;
  }
}

import { PrismaClient } from "@prisma/client";
import { startKeepalive } from "./prisma-retry.js";

/**
 * Append pool_timeout to the DATABASE_URL if not already present.
 * This gives Prisma more time to acquire a connection from the pool,
 * which is critical for serverless databases (e.g. Neon) on cold starts.
 */
function getDatabaseUrl(): string {
  const url = process.env.DATABASE_URL ?? "";
  if (!url || url.includes("pool_timeout")) return url;
  const separator = url.includes("?") ? "&" : "?";
  return `${url}${separator}pool_timeout=30`;
}

const globalForPrisma = globalThis as unknown as {
  socketPrisma?: PrismaClient;
};

export const prisma =
  globalForPrisma.socketPrisma ??
  new PrismaClient({
    datasources: { db: { url: getDatabaseUrl() } },
    log: process.env.NODE_ENV === "development" ? ["error", "warn"] : ["error"],
  });

if (process.env.NODE_ENV !== "production") {
  globalForPrisma.socketPrisma = prisma;
}

startKeepalive(prisma);

import { Redis } from "ioredis";
import { env } from "./env.js";

let client: Redis | null = null;

export function getRedis(): Redis {
  if (client) return client;
  client = new Redis(env.redisUrl, {
    maxRetriesPerRequest: 3,
    enableReadyCheck: true,
    lazyConnect: false,
  });
  client.on("error", (err) => {
    console.error("[redis] error:", err);
  });
  return client;
}

export async function closeRedis(): Promise<void> {
  if (client) {
    await client.quit();
    client = null;
  }
}

import { prisma } from "./prisma.js";
import { withDbRetry } from "./prisma-retry.js";
import { getRedis } from "./redis.js";
import {
  biddersKey,
  itemKey,
  resolvedListKey,
  roomKey,
  spectatorsKey,
} from "./keys.js";
import {
  type AuctionItem,
  type LiveItemState,
  type LiveRoomState,
  type LiveBid,
  type ResolvedItem,
  type RoomParticipant,
  type RoomStatus,
  AUCTION_ROOM,
} from "@auction/shared";

export interface RoomMeta {
  id: string;
  code: string;
  status: RoomStatus;
  auctioneerId: string;
  perRoomBudget: number;
  minIncrement: number;
  itemDurationSeconds: number;
}

export async function loadRoomMeta(roomId: string): Promise<RoomMeta | null> {
  const room = await withDbRetry(() =>
    prisma.room.findUnique({
      where: { id: roomId },
      select: {
        id: true,
        code: true,
        status: true,
        auctioneerId: true,
        perRoomBudget: true,
        minIncrement: true,
        itemDurationSeconds: true,
      },
    }),
  );
  if (!room) return null;
  return {
    id: room.id,
    code: room.code,
    status: room.status,
    auctioneerId: room.auctioneerId,
    perRoomBudget: room.perRoomBudget,
    minIncrement: room.minIncrement,
    itemDurationSeconds: room.itemDurationSeconds,
  };
}

export async function loadItemsFromDb(roomId: string): Promise<AuctionItem[]> {
  const items = await withDbRetry(() =>
    prisma.auctionItem.findMany({
      where: { roomId },
      orderBy: { slotIndex: "asc" },
    }),
  );
  return items.map((i) => ({
    id: i.id,
    roomId: i.roomId,
    slotIndex: i.slotIndex,
    name: i.name,
    description: i.description,
    imageUrl: i.imageUrl ?? null,
    startingPrice: i.startingPrice,
    status: i.status,
    winnerId: i.winnerId ?? null,
    winningBid: i.winningBid ?? null,
  }));
}

export async function loadParticipants(
  roomId: string,
  perRoomBudget: number,
): Promise<RoomParticipant[]> {
  const participants = await withDbRetry(() =>
    prisma.roomParticipant.findMany({
      where: { roomId },
      include: { user: { select: { name: true, activeRole: true } } },
      orderBy: { joinedAt: "asc" },
    }),
  );
  return participants.map((p) => ({
    userId: p.userId,
    name: p.user?.name ?? "",
    role: p.user?.activeRole ?? "BIDDER",
    budget: p.budget,
    reserved: p.reserved,
    available: Math.max(0, p.budget - p.reserved - p.spent),
    spent: p.spent,
  })) as RoomParticipant[];
}

export async function syncBiddersToRedis(
  roomId: string,
  participants: RoomParticipant[],
): Promise<void> {
  const redis = getRedis();
  const hashEntries: string[] = [];
  for (const p of participants) {
    hashEntries.push(p.userId, JSON.stringify(p));
  }
  if (hashEntries.length > 0) {
    await redis.hset(biddersKey(roomId), ...hashEntries);
  }
}

export async function getRedisBidders(
  roomId: string,
): Promise<RoomParticipant[]> {
  const redis = getRedis();
  const all = await redis.hgetall(biddersKey(roomId));
  return Object.values(all)
    .map((json) => JSON.parse(json) as RoomParticipant)
    .sort((a, b) => a.userId.localeCompare(b.userId));
}

export async function initRoomRedisState(
  meta: RoomMeta,
  participants: RoomParticipant[],
): Promise<void> {
  const redis = getRedis();
  await redis.hset(roomKey(meta.id), {
    status: meta.status,
    auctioneerId: meta.auctioneerId,
    perRoomBudget: String(meta.perRoomBudget),
    minIncrement: String(meta.minIncrement),
    itemDurationSeconds: String(meta.itemDurationSeconds),
    activeItemIndex: "",
    paused: "0",
    pausedAccumulatedMs: "0",
  });
  await syncBiddersToRedis(meta.id, participants);
}

export async function readRoomStatus(roomId: string): Promise<RoomStatus | null> {
  const redis = getRedis();
  const status = await redis.hget(roomKey(roomId), "status");
  return (status as RoomStatus) ?? null;
}

export async function setRoomStatus(
  roomId: string,
  status: RoomStatus,
): Promise<void> {
  const redis = getRedis();
  await redis.hset(roomKey(roomId), "status", status);
  const data: { status: RoomStatus; completedAt?: Date } = { status };
  if (status === "COMPLETED") {
    data.completedAt = new Date();
  }
  try {
    await prisma.room.update({ where: { id: roomId }, data });
  } catch (err) {
    console.error(`[setRoomStatus] failed to persist status=${status} for room=${roomId}:`, err);
  }
}

export async function startItem(
  roomId: string,
  item: AuctionItem,
  itemDurationSeconds: number,
): Promise<LiveItemState> {
  const redis = getRedis();
  const endsAt = Date.now() + itemDurationSeconds * 1000;
  const itemK = itemKey(roomId, item.id);
  await redis.hset(itemK, {
    slotIndex: String(item.slotIndex),
    name: item.name,
    imageUrl: item.imageUrl ?? "",
    startingPrice: String(item.startingPrice),
    status: "ACTIVE",
    highBidUserId: "",
    highBidUserName: "",
    highBidAmount: "0",
    highBidPlacedAtMs: "0",
    endsAt: String(endsAt),
    paused: "0",
    pausedAt: "0",
    pausedAccumulatedMs: "0",
  });
  await redis.hset(roomKey(roomId), {
    activeItemIndex: String(item.slotIndex),
    activeItemId: item.id,
  });
  await prisma.auctionItem
    .updateMany({
      where: { id: item.id, roomId, status: "PENDING" },
      data: { status: "ACTIVE" },
    })
    .catch((err) => {
      console.error(`[startItem] failed to update item status for item=${item.id}:`, err);
    });
  await prisma.room
    .update({
      where: { id: roomId },
      data: { activeItemIndex: item.slotIndex },
    })
    .catch((err) => {
      console.error(`[startItem] failed to update room activeItemIndex for room=${roomId}:`, err);
    });
  return liveItemFromRedis(roomId, item, {
    endsAt,
    paused: false,
    pausedAccumulatedMs: 0,
    highBid: null,
  });
}

function liveItemFromRedis(
  roomId: string,
  item: AuctionItem,
  state: {
    endsAt: number;
    paused: boolean;
    pausedAccumulatedMs: number;
    highBid: LiveBid | null;
  },
): LiveItemState {
  return {
    itemId: item.id,
    slotIndex: item.slotIndex,
    name: item.name,
    imageUrl: item.imageUrl,
    startingPrice: item.startingPrice,
    status: item.status,
    highBid: state.highBid,
    endsAt: state.endsAt > 0 ? state.endsAt : null,
    paused: state.paused,
    pausedAccumulatedMs: state.pausedAccumulatedMs,
  };
}

export async function readLiveItem(
  roomId: string,
  item: AuctionItem,
): Promise<LiveItemState> {
  const redis = getRedis();
  const hash = await redis.hgetall(itemKey(roomId, item.id));
  if (!hash || Object.keys(hash).length === 0) {
    return liveItemFromRedis(roomId, item, {
      endsAt: 0,
      paused: false,
      pausedAccumulatedMs: 0,
      highBid: null,
    });
  }

  const highUserId = hash.highBidUserId ?? "";
  const highAmount = Number(hash.highBidAmount ?? 0);
  const highBid: LiveBid | null =
    highUserId && highAmount > 0
      ? {
          userId: highUserId,
          userName: hash.highBidUserName ?? "",
          amount: highAmount,
          placedAt:
            hash.highBidPlacedAtMs && hash.highBidPlacedAtMs !== "0"
              ? new Date(Number(hash.highBidPlacedAtMs)).toISOString()
              : new Date(0).toISOString(),
        }
      : null;

  return {
    itemId: item.id,
    slotIndex: item.slotIndex,
    name: item.name,
    imageUrl: item.imageUrl,
    startingPrice: item.startingPrice,
    status: (hash.status as AuctionItem["status"]) ?? item.status,
    highBid,
    endsAt: hash.endsAt && hash.endsAt !== "0" ? Number(hash.endsAt) : null,
    paused: hash.paused === "1",
    pausedAccumulatedMs: Number(hash.pausedAccumulatedMs ?? 0),
  };
}

export async function pauseActiveItem(
  roomId: string,
  itemId: string,
): Promise<{ paused: boolean; endsAt: number | null } | null> {
  const redis = getRedis();
  const itemK = itemKey(roomId, itemId);

  const paused = await redis.hget(itemK, "paused");
  if (paused === "1") {
    const endsAtStr = await redis.hget(itemK, "endsAt");
    return {
      paused: true,
      endsAt: endsAtStr && endsAtStr !== "0" ? Number(endsAtStr) : null,
    };
  }

  const now = Date.now();
  const result = await redis.eval(
    `local cur = redis.call('HGET', KEYS[1], 'paused')
     if cur == '1' then return 0 end
     redis.call('HSET', KEYS[1], 'paused', '1', 'pausedAt', ARGV[1])
     return 1`,
    1,
    itemK,
    String(now),
  );

  if (result === 0) {
    const endsAtStr = await redis.hget(itemK, "endsAt");
    return {
      paused: true,
      endsAt: endsAtStr && endsAtStr !== "0" ? Number(endsAtStr) : null,
    };
  }

  const endsAtStr = await redis.hget(itemK, "endsAt");
  return {
    paused: true,
    endsAt: endsAtStr && endsAtStr !== "0" ? Number(endsAtStr) : null,
  };
}

export async function resumeActiveItem(
  roomId: string,
  itemId: string,
): Promise<{ paused: boolean; endsAt: number | null } | null> {
  const redis = getRedis();
  const itemK = itemKey(roomId, itemId);

  const paused = await redis.hget(itemK, "paused");
  if (paused !== "1") {
    const endsAtStr = await redis.hget(itemK, "endsAt");
    return {
      paused: false,
      endsAt: endsAtStr && endsAtStr !== "0" ? Number(endsAtStr) : null,
    };
  }

  const now = Date.now();
  const result = await redis.eval(
    `local cur = redis.call('HGET', KEYS[1], 'paused')
     if cur ~= '1' then return 0 end
     local pausedAt = tonumber(redis.call('HGET', KEYS[1], 'pausedAt')) or 0
     local oldEndsAt = tonumber(redis.call('HGET', KEYS[1], 'endsAt')) or 0
     local oldAcc = tonumber(redis.call('HGET', KEYS[1], 'pausedAccumulatedMs')) or 0
     local delta = 0
     if pausedAt > 0 then delta = tonumber(ARGV[1]) - pausedAt end
     local newAcc = oldAcc + delta
     local newEndsAt = oldEndsAt
     if oldEndsAt > 0 then newEndsAt = oldEndsAt + delta end
     redis.call('HSET', KEYS[1], 'paused', '0', 'pausedAt', '0', 'pausedAccumulatedMs', tostring(newAcc), 'endsAt', tostring(newEndsAt))
     return tostring(newEndsAt)`,
    1,
    itemK,
    String(now),
  );

  if (result === 0) {
    const endsAtStr = await redis.hget(itemK, "endsAt");
    return {
      paused: false,
      endsAt: endsAtStr && endsAtStr !== "0" ? Number(endsAtStr) : null,
    };
  }

  const newEndsAt = Number(result);
  return {
    paused: false,
    endsAt: newEndsAt > 0 ? newEndsAt : null,
  };
}

export async function setActiveItemIndexRedis(
  roomId: string,
  slotIndex: number | null,
  itemId: string | null,
): Promise<void> {
  const redis = getRedis();
  await redis.hset(roomKey(roomId), {
    activeItemIndex: slotIndex === null ? "" : String(slotIndex),
    activeItemId: itemId ?? "",
  });
}

export async function getActiveItemId(roomId: string): Promise<string | null> {
  const redis = getRedis();
  const itemId = await redis.hget(roomKey(roomId), "activeItemId");
  return itemId && itemId !== "" ? itemId : null;
}

export async function resolveItem(
  roomId: string,
  item: AuctionItem,
): Promise<ResolvedItem> {
  const redis = getRedis();

  const currentStatus = await redis.hget(itemKey(roomId, item.id), "status");
  if (currentStatus === "SOLD" || currentStatus === "UNSOLD") {
    const existing = await redis.lrange(resolvedListKey(roomId), 0, -1);
    for (const json of existing) {
      const parsed = JSON.parse(json) as ResolvedItem;
      if (parsed.itemId === item.id) return parsed;
    }
  }

  const hash = await redis.hgetall(itemKey(roomId, item.id));
  const highUserId = hash.highBidUserId ?? "";
  const highAmount = Number(hash.highBidAmount ?? 0);
  const hasWinner = highUserId !== "" && highAmount > 0;

  const winnerId = hasWinner ? highUserId : null;
  const winningBid = hasWinner ? highAmount : null;

  let winnerName: string | null = null;
  if (hasWinner) {
    const winnerJson = await redis.hget(biddersKey(roomId), winnerId!);
    if (winnerJson) {
      try {
        const winner = JSON.parse(winnerJson) as RoomParticipant;
        winner.spent = (winner.spent ?? 0) + highAmount;
        winner.reserved = Math.max(0, (winner.reserved ?? 0) - highAmount);
        winner.available = Math.max(
          0,
          (winner.budget ?? 0) - winner.spent - winner.reserved,
        );
        await redis.hset(biddersKey(roomId), winnerId!, JSON.stringify(winner));
        winnerName = winner.name;
      } catch (err) {
        console.error("[resolveItem] failed to update winner redis state:", err);
      }
    }
  }

  const newStatus = hasWinner ? "SOLD" : "UNSOLD";
  await redis.hset(itemKey(roomId, item.id), {
    status: newStatus,
    resolvedAtMs: String(Date.now()),
  });

  const resolved: ResolvedItem = {
    itemId: item.id,
    slotIndex: item.slotIndex,
    name: item.name,
    description: item.description,
    imageUrl: item.imageUrl,
    status: newStatus,
    winnerId,
    winnerName,
    winningBid,
    resolvedAt: new Date().toISOString(),
  };

  await redis.rpush(resolvedListKey(roomId), JSON.stringify(resolved));

  try {
    await prisma.$transaction(async (tx) => {
      await tx.auctionItem.update({
        where: { id: item.id },
        data: {
          status: newStatus,
          winnerId,
          winningBid,
          resolvedAt: new Date(),
        },
      });

      if (hasWinner && winnerId) {
        await tx.winner.upsert({
          where: { roomId_itemId: { roomId, itemId: item.id } },
          update: {},
          create: { roomId, itemId: item.id, userId: winnerId, amount: highAmount },
        });
        await tx.roomParticipant.update({
          where: { roomId_userId: { roomId, userId: winnerId } },
          data: {
            reserved: { decrement: highAmount },
            spent: { increment: highAmount },
          },
        });
      }
    });
  } catch (err) {
    console.error("[resolveItem] prisma transaction failed:", err);
  }

  return resolved;
}

