import { AuthenticatedRequest } from "../middleware/auth.middleware";
import { Response, NextFunction } from "express";
import { prisma } from "../db/prisma.db";
import { enqueueAnalysisJob } from "../queues/analysis.queue";
import { logger } from "../config/logger.config";
import { AnalysisStatus } from "@prisma/client";

export async function runAnalysis(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  const uploadId = req.params.uploadId;
  const user = req.user;
  if (!user) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  if (!uploadId) {
    return res.status(400).json({ error: "uploadId is required" });
  }

  try {
    const upload = await prisma.upload.findUnique({
      where: { uploadId },
      include: { parseResult: true },
    });
    if (!upload) {
      return res.status(404).json({ error: "Upload not found" });
    }
    if (upload.userId !== user.userId) {
      return res.status(403).json({ error: "Forbidden" });
    }

    const parsedText = upload.parseResult?.text;
    if (!parsedText) {
      return res.status(404).json({ error: "parse result not found" });
    }

    const mode: "homework" | "assignment" =
      req.body?.mode === "assignment" ? "assignment" : "homework";

    // Create the AnalysisResult first, then enqueue with a deterministic jobId
    // derived from analysisId. On enqueue failure, flip the row to failed so
    // the client never sees a "queued" row with no worker attached.
    const newAnalysis = await prisma.analysisResult.create({
      data: {
        uploadId: upload.uploadId,
        output: {} as any,
        status: AnalysisStatus.queued,
      },
    });

    try {
      await enqueueAnalysisJob("analyzeJobs", {
        analysisId: newAnalysis.id,
        uploadId,
        mode,
      });
    } catch (enqueueError) {
      // Roll back the row state so it cannot sit in "queued" forever.
      await prisma.analysisResult
        .update({
          where: { id: newAnalysis.id },
          data: {
            status: AnalysisStatus.failed,
            error: "Failed to enqueue analysis job",
          },
        })
        .catch(() => void 0);
      throw enqueueError;
    }

    return res.status(201).json({
      message: "Analysis enqueued",
      payload: { analysisId: newAnalysis.id },
    });
  } catch (error) {
    logger.error("Error running analysis", { error, uploadId });
    return next(error);
  }
}

export async function getAnalysis(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  const uploadId = req.params.uploadId;
  const analysisId = req.params.analysisId;
  const user = req.user;
  if (!user) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  if (!uploadId || !analysisId) {
    return res
      .status(400)
      .json({ error: "uploadId and analysisId are required" });
  }

  try {
    // Filter the analysis by its parent upload's owner so the lookup itself
    // cannot return another user's analysis (defense in depth against IDOR).
    const analysis = await prisma.analysisResult.findFirst({
      where: {
        id: analysisId,
        uploadId,
        upload: { userId: user.userId },
      },
    });

    if (!analysis) {
      return res.status(404).json({ error: "Analysis not found" });
    }

    return res
      .status(200)
      .json({ message: "Analysis found", payload: analysis.output });
  } catch (error) {
    return next(error);
  }
}

import { Request, Response, NextFunction } from "express";
import { prisma } from "../db/prisma.db";
import { loginSchema, registerSchema } from "../schema/auth.schema";
import jwt, { type JwtPayload } from "jsonwebtoken";
import bcrypt from "bcrypt";
import { config } from "../config/app.config";
import { Prisma } from "@prisma/client";
import {
  AUTH_COOKIE_NAME,
  TOKEN_TTL_SECONDS,
  setAuthCookie,
  clearAuthCookie,
} from "../config/cookies.config";

const BCRYPT_COST = 12;
const JWT_ALGORITHM = "HS256";

// Precomputed hash used when a login targets a non-existent email. Running
// bcrypt.compare against it keeps the failure timing identical to a real
// mismatch, preventing user enumeration via response timing.
const DUMMY_HASH = bcrypt.hashSync("__nonexistent__", BCRYPT_COST);

function signToken(userId: string): { token: string; expiresAt: number } {
  const expiresAt = Math.floor(Date.now() / 1000) + TOKEN_TTL_SECONDS;
  const token = jwt.sign({ userId, exp: expiresAt } as JwtPayload, config.jwtSecret, {
    algorithm: JWT_ALGORITHM,
  });
  return { token, expiresAt };
}

function publicUser(user: { userId: string; name: string; email: string }) {
  return { userId: user.userId, name: user.name, email: user.email };
}

/**
 * Validate the caller's JWT against the database and return the current user
 * along with the token's expiry (unix seconds). The SPA uses `expiresAt` to
 * schedule a proactive refresh / logout before the cookie actually expires —
 * the cookie itself is HttpOnly so the client can't decode `exp` from JS.
 */
export async function me(req: Request, res: Response, next: NextFunction) {
  const userId = (req as any).user?.userId;
  if (!userId) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  try {
    const user = await prisma.user.findUnique({
      where: { userId },
      select: { userId: true, name: true, email: true },
    });
    if (!user) {
      return res.status(401).json({ error: "Unauthorized" });
    }
    // Re-derive expiresAt from the bearer that just verified. The JWT payload
    // carries the `exp` claim, so use it rather than recomputing.
    const expClaim = (req as any).jwtExp as number | undefined;
    const expiresAt =
      typeof expClaim === "number"
        ? expClaim
        : Math.floor(Date.now() / 1000) + TOKEN_TTL_SECONDS;
    return res.json({ user: publicUser(user), expiresAt });
  } catch (error) {
    return next(error);
  }
}

export async function login(req: Request, res: Response, next: NextFunction) {
  const parsed = loginSchema.safeParse(req.body);
  if (!parsed.success) {
    return next(parsed.error);
  }

  const { email, password } = parsed.data;

  try {
    const user = await prisma.user.findUnique({ where: { email } });
    // Always compare against a hash to avoid timing-based user enumeration.
    const isMatch = await bcrypt.compare(
      password,
      user ? user.password : DUMMY_HASH,
    );

    if (!user || !isMatch) {
      return res.status(401).json({ error: "Invalid credentials" });
    }

    const { token, expiresAt } = signToken(user.userId);
    setAuthCookie(res, token);
    return res.json({ user: publicUser(user), expiresAt });
  } catch (error) {
    return next(error);
  }
}

export async function register(
  req: Request,
  res: Response,
  next: NextFunction,
) {
  const parsed = registerSchema.safeParse(req.body);
  if (!parsed.success) {
    return next(parsed.error);
  }

  const { name, email, password } = parsed.data;

  try {
    const hashedPassword = await bcrypt.hash(password, BCRYPT_COST);
    const user = await prisma.user.create({
      data: { name, email, password: hashedPassword },
    });

    const { token, expiresAt } = signToken(user.userId);
    setAuthCookie(res, token);
    return res.status(201).json({ user: publicUser(user), expiresAt });
  } catch (error) {
    // Rely on the unique constraint instead of a speculative findUnique.
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      return res.status(409).json({ error: "User already exists" });
    }
    return next(error);
  }
}

/**
 * Server-side logout: clear the auth cookie so the session can no longer be
 * used even from a state-stealing attacker. Stateful JWTs aren't revocable
 * without a denylist, but clearing the cookie stops the browser from sending
 * it again — that closes the most common leak path.
 */
export async function logout(_req: Request, res: Response) {
  clearAuthCookie(res);
  return res.status(204).end();
}

import type { NextFunction, Response } from "express";
import { config } from "../config/app.config";
import { logger } from "../config/logger.config";
import { prisma } from "../db/prisma.db";
import type { AuthenticatedRequest } from "../middleware/auth.middleware";
import {
  parseDocument,
  type SupportedDocumentKind,
} from "../services/document.parse.service";
import { getObjectBuffer } from "../services/storage.service";
import { magicBytesMatchMime } from "../utils/file-type.util";

const MIME_BY_KIND: Record<SupportedDocumentKind, string> = {
  pdf: "application/pdf",
  docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
};

async function markFailed(uploadId: string, error: string): Promise<void> {
  await prisma.upload
    .update({
      where: { uploadId },
      data: { status: "failed", error },
    })
    .catch(() => void 0);
}

async function parseUpload(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
  kind: SupportedDocumentKind,
) {
  const user = req.user;
  if (!user) return res.status(401).json({ error: "Unauthorized" });

  const uploadId = req.params.uploadId;
  if (!uploadId) {
    return res.status(400).json({ error: "Missing uploadId" });
  }

  try {
    const upload = await prisma.upload.findUnique({ where: { uploadId } });
    if (!upload) return res.status(404).json({ error: "Upload not found" });
    if (upload.userId !== user.userId) {
      return res.status(403).json({ error: "Forbidden" });
    }

    await prisma.upload.update({
      where: { uploadId },
      data: { status: "processing", error: null },
    });

    if (upload.size && upload.size > config.maxFileSizeBytes) {
      await markFailed(uploadId, "File exceeds size limit");
      return res.status(413).json({ error: "File exceeds size limit" });
    }

    const buffer = await getObjectBuffer({
      bucket: upload.bucket,
      key: upload.key,
      maxBytes: config.maxFileSizeBytes,
    });
    const declaredMime = upload.mime ?? MIME_BY_KIND[kind];

    if (!magicBytesMatchMime(buffer, declaredMime)) {
      await markFailed(uploadId, "File content does not match its type");
      return res
        .status(415)
        .json({ error: "File content does not match its declared type" });
    }

    let result = await parseDocument(buffer, kind);
    if (!result.text.trim()) {
      if (kind === "pdf" && result.diagnostics.visualFallbackRecommended) {
        result = {
          ...result,
          text:
            "The PDF has no embedded text. Read the attached visual PDF directly and preserve its page order.",
        };
      } else {
        await markFailed(uploadId, "No extractable text found");
        return res.status(422).json({
          error: "No extractable text found in the DOCX.",
          diagnostics: result.diagnostics,
        });
      }
    }

    const hasWarnings = result.diagnostics.warnings.length > 0;
    await prisma.$transaction([
      prisma.parseResult.upsert({
        where: { uploadId },
        create: {
          uploadId,
          text: result.text,
          content: result.blocks as any,
          diagnostics: result.diagnostics as any,
          ...(result.numPages === undefined
            ? {}
            : { numPages: result.numPages }),
        },
        update: {
          text: result.text,
          content: result.blocks as any,
          diagnostics: result.diagnostics as any,
          ...(result.numPages === undefined
            ? {}
            : { numPages: result.numPages }),
        },
      }),
      prisma.upload.update({
        where: { uploadId },
        data: {
          status: hasWarnings ? "processed_with_warnings" : "processed",
          processedAt: new Date(),
          error: hasWarnings
            ? `${result.diagnostics.warnings.length} extraction warning(s)`
            : null,
        },
      }),
    ]);

    logger.info("Document parsed", {
      uploadId,
      kind,
      characters: result.diagnostics.characterCount,
      coverage: result.diagnostics.coverage,
      warnings: result.diagnostics.warnings.length,
    });
    return res.status(hasWarnings ? 206 : 200).json(result);
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Unknown parse failure";
    logger.error("Document parsing failed", {
      uploadId,
      kind,
      error: message,
      stack: error instanceof Error ? error.stack : undefined,
    });

    if (
      error instanceof Error &&
      (error.name === "FileTooLargeError" ||
        error.message === "File exceeds size limit")
    ) {
      await markFailed(uploadId, "File exceeds size limit");
      return res.status(413).json({ error: "File exceeds size limit" });
    }

    await markFailed(uploadId, "Parse failure");
    return next(error);
  }
}

export function parsePDFController(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  return parseUpload(req, res, next, "pdf");
}

export function parseDocxController(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  return parseUpload(req, res, next, "docx");
}

import { Response, NextFunction } from "express";
import { prisma } from "../db/prisma.db";
import { s3 } from "../config/storage.config";
import { GetObjectCommand } from "@aws-sdk/client-s3";
import { Readable } from "stream";
import { AuthenticatedRequest } from "../middleware/auth.middleware";
import { ParsedResult } from "../types/parsed-result.types";
import { logger } from "../config/logger.config";
import { parseDocx } from "../services/docx.parse.service";
import { config } from "../config/app.config";
import { magicBytesMatchMime } from "../utils/file-type.util";

/**
 * @deprecated Retained as legacy code. No application route imports this
 * controller.
 */
export async function parseDocxController(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  const user = req.user;
  if (!user) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  const uploadId = req.params.uploadId;
  if (!uploadId) {
    return res.status(400).json({ error: "Missing uploadId" });
  }

  try {
    const upload = await prisma.upload.findUnique({
      where: {
        uploadId: uploadId,
      },
    });
    if (!upload) {
      return res.status(404).json({ error: "Upload not found" });
    }
    if (upload.userId !== req.user?.userId) {
      return res.status(403).json({ error: "Forbidden" });
    }

    await prisma.upload.update({
      where: {
        uploadId: uploadId,
      },
      data: {
        status: "processing",
      },
    });

    // Enforce server-side size cap before buffering into memory.
    if (upload.size && upload.size > config.maxFileSizeBytes) {
      await prisma.upload.update({
        where: { uploadId: uploadId },
        data: { status: "failed", error: "File exceeds size limit" },
      });
      return res.status(413).json({ error: "File exceeds size limit" });
    }

    const command = new GetObjectCommand({
      Bucket: upload.bucket,
      Key: upload.key,
    });

    const response = await s3.send(command);
    const body = response.Body;

    logger.debug("S3 response received", {
      contentType: response.ContentType,
      contentLength: response.ContentLength,
      bodyType: typeof body,
      isReadable: body instanceof Readable,
    });

    if (body instanceof Readable) {
      const chunks: Buffer[] = [];
      let accumulated = 0;
      for await (const chunk of body) {
        accumulated += chunk.length;
        if (accumulated > config.maxFileSizeBytes) {
          await prisma.upload.update({
            where: { uploadId },
            data: { status: "failed", error: "File exceeds size limit" },
          });
          return res.status(413).json({ error: "File exceeds size limit" });
        }
        chunks.push(chunk as Buffer);
      }
      const buffer = Buffer.concat(chunks);

      logger.debug("DOCX buffer created", {
        bufferSize: buffer.length,
      });
      // Magic-byte check before handing bytes to officeparser (defense against
      // poisoned/mislabeled files uploaded via the presigned URL).
      const declaredMime =
        upload.mime ??
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
      if (!magicBytesMatchMime(buffer, declaredMime)) {
        await prisma.upload.update({
          where: { uploadId },
          data: { status: "failed", error: "File content does not match its type" },
        }).catch(() => void 0);
        logger.warn("DOCX magic-byte mismatch", { uploadId });
        return res
          .status(415)
          .json({ error: "File content does not match its declared type" });
      }

      const docxText = await parseDocx(buffer);

      logger.info("DOCX parsed successfully", {
        uploadId,
        textLength: docxText.length || 0,
      });

      if (!docxText || docxText === "") {
        logger.warn("Parsed DOCX text is empty", { uploadId });
        await prisma.upload.update({
          where: {
            uploadId: uploadId,
          },
          data: {
            status: "failed",
          },
        });
        return res
          .status(400)
          .json({ error: "Failed to parse DOCX: No text content found" });
      }

      await prisma.upload.update({
        where: {
          uploadId: uploadId,
        },
        data: {
          status: "processed",
        },
      });

      await prisma.parseResult.upsert({
        where: {
          uploadId: uploadId,
        },
        create: {
          uploadId: uploadId,
          text: docxText,
        },
        update: {
          text: docxText,
        },
      });
      return res.json(docxText);
    }
    await prisma.upload.update({
      where: { uploadId },
      data: { status: "failed", error: "Storage stream unavailable" },
    }).catch(() => void 0);
    return res.status(500).json({ error: "Failed to parse DOCX" });
  } catch (e) {
    logger.error("Error in parseDocxController", {
      uploadId,
      error: e instanceof Error ? e.message : "Unknown error",
      stack: e instanceof Error ? e.stack : undefined,
    });
    await prisma.upload.update({
      where: { uploadId },
      data: { status: "failed", error: "Parse failure" },
    }).catch(() => void 0);
    return next(e);
  }
}

import { Request, Response } from "express";
import { prisma } from "../db/prisma.db";
import { redis } from "../config/redis.config";
import { s3, storageBucket } from "../config/storage.config";
import { HeadBucketCommand } from "@aws-sdk/client-s3";
import { logger } from "../config/logger.config";

export async function healthCheck(req: Request, res: Response) {
  res.status(200).json({
    status: "ok",
    timestamp: new Date().toISOString(),
  });
}

export async function readinessCheck(req: Request, res: Response) {
  const checks = {
    database: false,
    redis: false,
    storage: false,
  };

  let allHealthy = true;

  try {
    await prisma.$queryRaw`SELECT 1`;
    checks.database = true;
  } catch (error) {
    allHealthy = false;
    logger.error("Database health check failed", { error });
  }

  try {
    if (redis) {
      await redis.ping();
      checks.redis = true;
    } else {
      checks.redis = true; 
    }
  } catch (error) {
    allHealthy = false;
    logger.error("Redis health check failed", { error });
  }

  try {
    await s3.send(new HeadBucketCommand({ Bucket: storageBucket }));
    checks.storage = true;
  } catch (error) {
    allHealthy = false;
    logger.error("Storage health check failed", { error });
  }

  const statusCode = allHealthy ? 200 : 503;

  res.status(statusCode).json({
    status: allHealthy ? "ready" : "not ready",
    timestamp: new Date().toISOString(),
    checks,
  });
}

