  res: Response,
  next: NextFunction,
) {
  const user = req.user;
  if (!user) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  const uploadId = req.params.uploadId;
  if (!uploadId) {
    return res.status(400).json({ error: "Missing uploadId" });
  }

  try {
    const upload = await prisma.upload.findUnique({
      where: {
        uploadId: uploadId,
      },
    });
    if (!upload) {
      return res.status(404).json({ error: "Upload not found" });
    }

    if (upload.userId !== req.user?.userId) {
      return res.status(403).json({ error: "Forbidden" });
    }

    await prisma.upload.update({
      where: {
        uploadId: uploadId,
      },
      data: {
        status: "processing",
      },
    });

    // Enforce server-side size cap before buffering into memory.
    if (upload.size && upload.size > config.maxFileSizeBytes) {
      await prisma.upload.update({
        where: { uploadId: uploadId },
        data: { status: "failed", error: "File exceeds size limit" },
      });
      return res.status(413).json({ error: "File exceeds size limit" });
    }

    const command = new GetObjectCommand({
      Bucket: upload.bucket,
      Key: upload.key,
    });

    const response = await s3.send(command);
    const body = response.Body;

    logger.debug("S3 response received", { 
      contentType: response.ContentType,
      contentLength: response.ContentLength,
      bodyType: typeof body,
      isReadable: body instanceof Readable
    });

    if (body instanceof Readable) {
      const chunks: Buffer[] = [];
      let accumulated = 0;
      for await (const chunk of body) {
        accumulated += chunk.length;
        if (accumulated > config.maxFileSizeBytes) {
          await prisma.upload.update({
            where: { uploadId },
            data: { status: "failed", error: "File exceeds size limit" },
          });
          return res.status(413).json({ error: "File exceeds size limit" });
        }
        chunks.push(chunk as Buffer);
      }
      const buffer = Buffer.concat(chunks);

      logger.debug("PDF buffer created", { 
        bufferSize: buffer.length 
      });

      // Magic-byte check before handing bytes to pdf-parse (defense against
      // poisoned/mislabeled files uploaded via the presigned URL).
      if (!magicBytesMatchMime(buffer, upload.mime ?? "application/pdf")) {
        await prisma.upload.update({
          where: { uploadId },
          data: { status: "failed", error: "File content does not match its type" },
        }).catch(() => void 0);
        logger.warn("PDF magic-byte mismatch", { uploadId });
        return res
          .status(415)
          .json({ error: "File content does not match its declared type" });
      }

      const pdfData = (await parsePDF(buffer)) as ParsedResult;

      logger.info("PDF parsed successfully", { 
        uploadId, 
        textLength: pdfData.text?.length || 0
      });

      if (!pdfData.text || pdfData.text === "") {
        logger.warn("Parsed PDF text is empty", { uploadId });
        await prisma.upload.update({
          where: {
            uploadId: uploadId,
          },
          data: {
            status: "failed",
          },
        });
        return res.status(400).json({ error: "Failed to parse PDF: No text content found" });
      }

      await prisma.upload.update({
        where: {
          uploadId: uploadId,
        },
        data: {
          status: "processed",
        },
      });

      await prisma.parseResult.upsert({
        where: {
          uploadId: uploadId,
        },
        create: {
          uploadId: uploadId,
          text: pdfData.text,
        },
        update: {
          text: pdfData.text,
        },
      });

      return res.json(pdfData);
    } else {
      logger.error("S3 body is not a readable stream", { uploadId, bodyType: typeof body });
      // Mark as failed so the row doesn't sit in "processing" forever.
      await prisma.upload.update({
        where: { uploadId },
        data: { status: "failed", error: "Storage stream unavailable" },
      }).catch(() => void 0);
      return res.status(500).json({ error: "Failed to parse PDF: storage error" });
    }
  } catch (e) {
    logger.error("Error in parsePDFController", {
      uploadId,
      error: e instanceof Error ? e.message : "Unknown error",
      stack: e instanceof Error ? e.stack : undefined,
    });
    await prisma.upload.update({
      where: { uploadId },
      data: { status: "failed", error: "Parse failure" },
    }).catch(() => void 0);
    return next(e);
  }
}

import { Response, NextFunction } from "express";
import { pasteSchema } from "../schema/paste.schema";
import { prisma } from "../db/prisma.db";
import { storageBucket } from "../config/storage.config";
import { AuthenticatedRequest } from "../middleware/auth.middleware";
import { logger } from "../config/logger.config";
import { sanitizeTextInput } from "../utils/format.utils";

export async function pasteText(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  const parsed = pasteSchema.safeParse(req.body);

  if (!parsed.success) {
    return next(parsed.error);
  }

  const user = req.user;
  if (!user) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const { text } = parsed.data;
  const sanitizedText = sanitizeTextInput(text);

  if (!sanitizedText) {
    return res
      .status(400)
      .json({ error: "Text content is empty after sanitization" });
  }

  try {
    // Create the upload row and its parse result atomically so a partial
    // failure cannot leave an orphaned upload with status "processed".
    const upload = await prisma.upload.create({
      data: {
        userId: user.userId,
        bucket: storageBucket,
        key: `paste_${user.userId}_${Date.now()}.txt`,
        status: "processed",
        parseResult: {
          create: { text: sanitizedText, numPages: 1 },
        },
      },
      include: { parseResult: true },
    });

    logger.info("Paste upload created", {
      uploadId: upload.uploadId,
      userId: user.userId,
      textLength: sanitizedText.length,
    });

    return res.status(201).json({ uploadId: upload.uploadId });
  } catch (error) {
    return next(error);
  }
}

import { Response, NextFunction } from "express";
import { AuthenticatedRequest } from "../middleware/auth.middleware";
import { prisma } from "../db/prisma.db";
import { renderSlimToPdfBuffer } from "../services/render.service";
import { resultSchema } from "../schema/result.schema";
import { s3 } from "../config/storage.config";
import { PutObjectCommand } from "@aws-sdk/client-s3";
import { presignGet, headObject } from "../services/storage.service";
import { logger } from "../config/logger.config";
import { getPdfExportKey } from "../utils/export-key.util";

/**
 * POST render — idempotent: if the PDF already exists in storage we just
 * return its download URL. Otherwise we generate and upload it. Cache key is
 * versioned so renderer upgrades cannot serve a stale artifact.
 */
export async function renderAnalysis(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  const user = req.user;
  const { uploadId, analysisId } = req.params;
  if (!user) return res.status(401).json({ error: "Unauthorized" });
  if (!uploadId || !analysisId) {
    return res.status(400).json({ error: "uploadId and analysisId are required" });
  }

  try {
    const upload = await prisma.upload.findUnique({ where: { uploadId } });
    if (!upload || upload.userId !== user.userId) {
      return res
        .status(upload ? 403 : 404)
        .json({ error: upload ? "Forbidden" : "Upload not found" });
    }

    const analysis = await prisma.analysisResult.findFirst({
      where: { uploadId, id: analysisId, upload: { userId: user.userId } },
    });
    if (!analysis) return res.status(404).json({ error: "Analysis not found" });

    const key = getPdfExportKey(uploadId, analysisId);

    // Cache hit — don't regenerate.
    try {
      await headObject({ key, bucket: upload.bucket });
      const { url } = await presignGet({ key, bucket: upload.bucket });
      return res.status(200).json({ key, pages: analysis.pages, url });
    } catch {
      // PDF doesn't exist yet — fall through to render.
    }

    const output = resultSchema.safeParse(analysis.output);
    if (!output.success) {
      return res
        .status(400)
        .json({ error: "Invalid output format", details: output.error.issues });
    }

    const { buffer, pages } = await renderSlimToPdfBuffer(output.data);

    await s3.send(
      new PutObjectCommand({
        Bucket: upload.bucket,
        Key: key,
        Body: buffer,
        ContentType: "application/pdf",
      }),
    );

    await prisma.analysisResult.update({
      where: { id: analysisId },
      data: { solutionBucket: upload.bucket, solutionKey: key, pages },
    });

    const { url } = await presignGet({ key, bucket: upload.bucket });
    return res.status(200).json({ key, pages, url });
  } catch (error: any) {
    logger.error("Failed to render analysis", {
      error: error?.message || error,
      stack: error?.stack,
      uploadId,
      analysisId,
    });
    return next(error);
  }
}

/**
 * GET download — read-only. Returns a fresh presigned URL for an already-
 * rendered solution PDF. Returns 404 if it has not been rendered yet (so the
 * client can call POST /render first). This makes the GET genuinely
 * idempotent: browsers, scanners, and curl retries no longer trigger S3
 * writes as a side effect.
 */
export async function getDownloadUrl(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  const user = req.user;
  const { uploadId, analysisId } = req.params;
  if (!user) return res.status(401).json({ error: "Unauthorized" });
  if (!uploadId || !analysisId) {
    return res
      .status(400)
      .json({ error: "uploadId and analysisId are required" });
  }

  try {
    const upload = await prisma.upload.findUnique({ where: { uploadId } });
    if (!upload || upload.userId !== user.userId) {
      return res
        .status(upload ? 403 : 404)
        .json({ error: upload ? "Forbidden" : "Upload not found" });
    }

    const analysis = await prisma.analysisResult.findFirst({
      where: { uploadId, id: analysisId, upload: { userId: user.userId } },
    });
    if (!analysis) return res.status(404).json({ error: "Analysis not found" });

    const key =
      analysis.solutionKey ?? getPdfExportKey(uploadId, analysisId);
    try {
      await headObject({ key, bucket: upload.bucket });
    } catch {
      return res.status(404).json({
        error:
          "Solution PDF has not been rendered yet. Call POST /render first.",
      });
    }

    const { url } = await presignGet({ key, bucket: upload.bucket });
    return res.status(200).json({ url });
  } catch (error: any) {
    logger.error("Failed to get download URL", {
      error: error?.message || error,
      uploadId,
      analysisId,
    });
    return next(error);
  }
}

import { Response, NextFunction } from "express";
import {
  presignSchema,
  confirmSchema,
  listUploadSchema,
} from "../schema/upload.schema";
import {
  presignPut,
  headObject,
  deleteObject,
  deleteObjectsByPrefix,
} from "../services/storage.service";
import { prisma } from "../db/prisma.db";
import { AuthenticatedRequest } from "../middleware/auth.middleware";
import { logger } from "../config/logger.config";
import { config } from "../config/app.config";
import { encodeCursor, decodeCursor } from "../utils/cursor.util";
import { getPdfExportPrefixes } from "../utils/export-key.util";

function sanitizeFilename(name: string) {
  return name.replace(/[^a-zA-Z0-9._-]/g, "_");
}

function sanitizeFolder(input?: string) {
  if (!input) return "";
  const clean = input.replace(/\\/g, "/").replace(/^\/+|\/+$/g, "");
  return clean ? `${clean}/` : "";
}

export async function presignUpload(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  const parsed = presignSchema.safeParse(req.body);

  if (!parsed.success) {
    return res.status(400).json({
      error: "Invalid request body",
      details: parsed.error.issues,
    });
  }

  const user = req.user;
  if (!user) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const { filename, contentType, folder, fileSize } = parsed.data;
  const timestamp = Date.now();
  const san = sanitizeFilename(filename);
  const ext =
    san.lastIndexOf(".") !== -1 ? san.substring(san.lastIndexOf(".")) : "";
  const name =
    san.lastIndexOf(".") !== -1 ? san.substring(0, san.lastIndexOf(".")) : san;

  // Namespace keys per user to prevent cross-user key enumeration/collision.
  const key = `${user.userId}/${sanitizeFolder(folder)}${name}_${timestamp}${ext}`;

  try {
    const { url, bucket, expiresAt } = await presignPut({
      key,
      contentType,
      contentLength: fileSize,
    });

    const newUpload = await prisma.upload.create({
      data: {
        userId: req.user?.userId as string,
        key,
        bucket,
        status: "uploading",
      },
    });

    res.status(200).json({
      uploadId: newUpload.uploadId,
      url,
      key,
      bucket,
      expiresAt,
    });
  } catch (e) {
    logger.error("Presign upload error", {
      error: e instanceof Error ? e.message : String(e),
      stack: e instanceof Error ? e.stack : undefined,
    });
    return next(e);
  }
}

export async function confirmUpload(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  const parsed = confirmSchema.safeParse(req.body);
  if (!parsed.success) {
    return next(parsed.error);
  }

  const user = req.user;
  if (!user) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const { bucket: clientBucket, key } = parsed.data;

  try {
    // Filter by userId upfront so foreign uploads return 404 instead of 403,
    // removing the existence oracle.
    const upload = await prisma.upload.findFirst({
      where: { userId: user.userId, bucket: clientBucket, key },
    });

    if (!upload) {
      return res.status(404).json({ error: "Upload not found" });
    }

    const meta = await headObject({ key, bucket: upload.bucket });

    // Server-side size enforcement: reject and clean up oversized objects.
    if (meta.contentLength > config.maxFileSizeBytes) {
      await prisma.upload
        .delete({ where: { uploadId: upload.uploadId } })
        .catch(() => void 0);
      await deleteObject({ key, bucket: upload.bucket }).catch(() => void 0);
      logger.warn("Rejected oversized upload at confirm", {
        uploadId: upload.uploadId,
        contentLength: meta.contentLength,
        limit: config.maxFileSizeBytes,
      });
      return res.status(413).json({ error: "File exceeds size limit" });
    }

    await prisma.upload.update({
      where: {
        bucket_key: { bucket: upload.bucket, key },
      },
      data: {
        status: "uploaded",
        confirmedAt: new Date(),
        size: meta.contentLength,
        mime: meta.contentType,
        etag: meta.etag,
      },
    });

    return res.status(200).json({
      bucket: upload.bucket,
      key,
      contentLength: meta.contentLength,
      contentType: meta.contentType,
      etag: meta.etag,
      lastModified: meta.lastModified,
    });
  } catch (e) {
    return next(e);
  }
}

export async function listUpload(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  const user = req.user;
  if (!user) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const parsed = listUploadSchema.safeParse(req.query);
  if (!parsed.success) {
    return res.status(400).json({ error: "Invalid query parameters" });
  }

  const { cursor, limit = 10 } = parsed.data;

  // Keyset pagination: when a cursor is present, decode the (createdAt, uploadId)
  // tuple and filter for everything strictly "before" that point in the
  // orderBy. This fixes duplicate/skipped items the original `cursor` on
  // uploadId produced because the orderBy used createdAt first.
  let cursorFilter: any = undefined;
  if (cursor) {
    const decoded = decodeCursor(cursor);
    if (!decoded) {
      return res.status(400).json({ error: "Invalid cursor" });
    }
    cursorFilter = {
      OR: [
        { createdAt: { lt: new Date(decoded.createdAt) } },
        {
          createdAt: { equals: new Date(decoded.createdAt) },
          uploadId: { lt: decoded.uploadId },
        },
      ],
    };
  }

  try {
    const listUploads = await prisma.upload.findMany({
      where: { userId: user.userId, ...(cursorFilter ? cursorFilter : {}) },
      take: limit + 1,
      orderBy: [{ createdAt: "desc" }, { uploadId: "desc" }],
      include: { analyses: true },
    });

    let nextCursor: string | null = null;
    if (listUploads.length > limit) {
      const nextItem = listUploads.pop();
      if (nextItem) {
        nextCursor = encodeCursor({
          createdAt: nextItem.createdAt.toISOString(),
          uploadId: nextItem.uploadId,
        });
      }
    }

    return res.status(200).json({
      items: listUploads,
      nextCursor,
    });
  } catch (error) {
    return next(error);
  }
}

export async function getUpload(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  const user = req.user;
  if (!user) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  const { uploadId } = req.params;
  if (!uploadId) {
    return res.status(400).json({ error: "Missing uploadId" });
  }
  try {
    const upload = await prisma.upload.findFirst({
      where: { uploadId, userId: user.userId },
      include: {
        parseResult: true,
        analyses: {
          orderBy: { createdAt: "desc" },
        },
      },
    });

    if (!upload) {
      return res.status(404).json({ error: "Upload not found" });
    }

    return res.status(200).json({ upload });
  } catch (error) {
    return next(error);
  }
}

export async function deleteUpload(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  const user = req.user;
  if (!user) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  const { uploadId } = req.params;
  if (!uploadId) {
    return res.status(400).json({ error: "Missing uploadId" });
  }

  try {
    const upload = await prisma.upload.findFirst({
      where: { uploadId, userId: user.userId },
      include: { analyses: true },
    });

    if (!upload) {
      return res.status(404).json({ error: "Upload not found" });
    }

    const storageErrors: string[] = [];

    try {
      await deleteObject({ key: upload.key, bucket: upload.bucket });
    } catch (error) {
      const msg = error instanceof Error ? error.message : "Unknown error";
      logger.error("Failed to delete original file from storage", {
        key: upload.key,
        bucket: upload.bucket,
        error: msg,
      });
      storageErrors.push(`Original file: ${msg}`);
    }

    for (const prefix of getPdfExportPrefixes(uploadId)) {
      try {
        await deleteObjectsByPrefix({
          prefix,
          bucket: upload.bucket,
        });
      } catch (error) {
        const msg = error instanceof Error ? error.message : "Unknown error";
        logger.error("Failed to delete export files from storage", {
          prefix,
          bucket: upload.bucket,
          error: msg,
        });
        storageErrors.push(`Export files (${prefix}): ${msg}`);
      }
    }

    for (const analysis of upload.analyses) {
      if (analysis.solutionKey) {
        try {
          await deleteObject({
            key: analysis.solutionKey,
            bucket: analysis.solutionBucket ?? upload.bucket,
          });
        } catch (error) {
          const msg = error instanceof Error ? error.message : "Unknown error";
          logger.error("Failed to delete analysis solution file from storage", {
            key: analysis.solutionKey,
            bucket: analysis.solutionBucket ?? upload.bucket,
            analysisId: analysis.id,
            error: msg,
          });
          storageErrors.push(`Analysis ${analysis.id} solution: ${msg}`);
        }
      }
    }

    await prisma.upload.delete({
      where: { uploadId },
    });

    logger.info("Upload deleted", {
      uploadId,
      storageErrors: storageErrors.length > 0 ? storageErrors : undefined,
    });

    return res.status(200).json({
      message: "Upload deleted successfully",
      storageCleanup:
        storageErrors.length > 0
          ? { warnings: storageErrors }
          : { status: "complete" },
    });
  } catch (error) {
    logger.error("Failed to delete upload", {
      uploadId,
      error: error instanceof Error ? error.message : "Unknown error",
    });
    return next(error);
  }
}

import jwt, { JwtPayload, Secret } from "jsonwebtoken";
import { Request, Response, NextFunction } from "express";
import { config } from "../config/app.config";
import { logger } from "../config/logger.config";
import { AUTH_COOKIE_NAME } from "../config/cookies.config";

const JWT_ALGORITHMS = ["HS256"] as const;

export interface AuthenticatedRequest extends Request {
  user?: {
    userId: string;
  };
  // unix seconds the JWT expires at; populated for downstream endpoints (e.g.
  // /auth/me) so they can reuse it without re-extracting from the token.
  jwtExp?: number | undefined;
}

function extractToken(req: Request): string | null {
  // Cookie-first: the SPA uses an HttpOnly cookie. Authorization header is
  // kept as a fallback for non-browser clients (CLI, native apps, tests).
  const cookieToken = (req.cookies as Record<string, string> | undefined)?.[
    AUTH_COOKIE_NAME
  ];
  if (cookieToken) return cookieToken;

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) return null;
  return authHeader.slice("Bearer ".length) ?? null;
}

export function authMiddleware(
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction,
) {
  const token = extractToken(req);
  if (!token) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  try {
    const payload = jwt.verify(token, config.jwtSecret as Secret, {
      algorithms: [...JWT_ALGORITHMS],
    });
    if (
      typeof payload !== "object" ||
      !payload ||
      typeof (payload as JwtPayload).userId !== "string"
    ) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    req.user = { userId: (payload as JwtPayload).userId as string };
    if (typeof (payload as JwtPayload).exp === "number") {
      req.jwtExp = (payload as JwtPayload).exp;
    }
    return next();
  } catch (error) {
    if (error instanceof jwt.TokenExpiredError) {
      logger.warn("Expired JWT presented", { error: error.message });
    } else if (error instanceof jwt.JsonWebTokenError) {
      logger.warn("Invalid JWT presented", { error: error.message });
    } else {
      logger.error("Unexpected JWT verification failure", {
        error: error instanceof Error ? error.message : String(error),
      });
    }
    return res.status(401).json({ error: "Unauthorized" });
  }
}

