export function buildAIPrompt(params: {
  subjectName: string;
  schoolName: string;
  className: string;
  duration: string;
  questionTypes: Array<{ type: string; count: number; marks: number }>;
  additionalInstructions?: string | null;
  totalMarks: number;
}): string {
  const {
    subjectName,
    schoolName,
    className,
    duration,
    questionTypes,
    additionalInstructions,
    totalMarks,
  } = params;

  const questionTypesStr = questionTypes
    .map((qt) => `- ${qt.type}: ${qt.count} questions, ${qt.marks} marks each`)
    .join("\n");

  return `Generate a comprehensive question paper for the following specifications:

Institution: ${schoolName}
Subject: ${subjectName}
Class: ${className}
Duration: ${duration}
Maximum Marks: ${totalMarks}

Question Type Distribution:
${questionTypesStr}

${additionalInstructions ? `Additional Instructions:\n${additionalInstructions}\n` : ""}

Requirements:
1. Create well-structured sections (A, B, C, etc.) based on question types and difficulty levels
2. Include a mix of Easy, Moderate, and Challenging questions
3. Each question should have a unique question ID (qid)
4. Provide an answer key for all questions
5. Include general instructions for students
6. Make questions relevant to the subject and class level
7. Ensure total marks match the specified maximum
8. For Multiple Choice Questions (MCQs), include 4 options (A, B, C, D) in the "options" array field
9. For non-MCQ questions, omit the "options" field or leave it empty

Generate the question paper in the exact JSON format specified.`;
}

import { Request, Response, NextFunction } from "express";
import jwt from "jsonwebtoken";
import { JWT_SECRET } from "../lib/constants";

export const authMiddleware = (req: Request, res: Response, next: NextFunction) => {
  try {
    const token = req.cookies?.token;
    if (!token) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    const decoded = jwt.verify(token, JWT_SECRET as string) as { id: string };
    req.userId = decoded.id;
    next();
  } catch (error) {
    return res.status(401).json({ error: "Invalid token" });
  }
};

import { prisma } from "../config/db.config";
import { Jobs } from "../types/job.types";
import { Job } from "bullmq";
import { jobSchema } from "../schemas/job.schema";
import { buildAIPrompt } from "../lib/prompt";
import { runLLM } from "../services/qpgenerator";

export async function processGenerateJob(job: Job<Jobs>) {
  const parsedJob = jobSchema.safeParse(job.data);
  if (!parsedJob.success) {
    throw new Error("Failed to parse job data");
  }
  const { assignmentId } = parsedJob.data;

  try {
    const assignment = await prisma.assignment.findFirst({
      where: {
        id: assignmentId,
      },
    });

    if (!assignment) {
      throw new Error("Assignment not found");
    }

    const {
      subjectName,
      schoolName,
      className,
      duration,
      dueDate,
      additionalInstructions,
      totalMarks,
    } = assignment;

    const questionTypes = assignment.questionTypes as Array<{
      type: string;
      count: number;
      marks: number;
    }>;

    const prompt = buildAIPrompt({
      subjectName: assignment.subjectName,
      schoolName: assignment.schoolName,
      className: assignment.className,
      duration: assignment.duration,
      questionTypes,
      additionalInstructions: assignment.additionalInstructions,
      totalMarks: assignment.totalMarks,
    });

    const qpData = await runLLM(prompt);

    await prisma.questionPaper.upsert({
      where: { assignmentId: assignment.id },
      update: {
        documentId: qpData.document_id,
        institutionName: qpData.paper_meta.institution_name,
        subject: qpData.paper_meta.subject,
        className: qpData.paper_meta.class_name,
        timeAllowed: qpData.paper_meta.time_allowed,
        maxMarks: qpData.paper_meta.max_marks,
        generalInstructions: qpData.paper_meta.general_instructions,
        sections: qpData.sections as any,
        answerKey: qpData.answer_key as any,
      },
      create: {
        assignmentId: assignment.id,
        documentId: qpData.document_id,
        institutionName: qpData.paper_meta.institution_name,
        subject: qpData.paper_meta.subject,
        className: qpData.paper_meta.class_name,
        timeAllowed: qpData.paper_meta.time_allowed,
        maxMarks: qpData.paper_meta.max_marks,
        generalInstructions: qpData.paper_meta.general_instructions,
        sections: qpData.sections as any,
        answerKey: qpData.answer_key as any,
      },
    });

    await prisma.assignment.update({
      where: { id: assignmentId },
      data: { status: "COMPLETED" },
    });
  } catch (error) {
    console.error("Error processing job (will retry if attempts remain):", error);
    throw error;
  }
}

import { Queue, JobsOptions } from "bullmq";
import { Jobs } from "../types/job.types";
import { redis } from "../config/redis.config";

if (!redis) {
  throw new Error(
    "Redis connection is required for job queues. Please set REDIS_URL in your .env file.",
  );
}

export const analyzeJobsQueue = new Queue<Jobs>("generateJobs", {
  connection: redis,
  defaultJobOptions: {
    attempts: 3,
    backoff: {
      type: "exponential",
      delay: 5000,
    },
    removeOnComplete: {
      count: 100,
      age: 24 * 3600,
    },
    removeOnFail: {
      count: 50,
      age: 7 * 24 * 3600,
    },
  } as JobsOptions,
});

export async function enqueueAnalysisJob(jobName: string, jobData: Jobs) {
  try {
    const job = await analyzeJobsQueue.add(jobName, jobData);
    return job;
  } catch (e) {
    throw new Error("Failed to enqueue job");
  }
}

