import { Redis, type RedisOptions } from "ioredis";
import * as dotenv from "dotenv";

dotenv.config();

const REDIS_URL = process.env.REDIS_URL || "redis://localhost:6379";

let circuitBreakerState = {
  isOpen: false,
  failureCount: 0,
  lastFailureTime: 0,
  threshold: 5,
  timeout: 60000,
};

const redisOptions: RedisOptions = {
  maxRetriesPerRequest: null,
  enableReadyCheck: true,
  lazyConnect: true,
  enableOfflineQueue: false,
  connectTimeout: 10000,
  commandTimeout: 15000,
};

export const redis = new Redis(REDIS_URL, redisOptions);

let connectionHealth = {
  isConnected: false,
  lastPing: 0,
  consecutiveFailures: 0,
};

export async function checkRedisHealth(): Promise<boolean> {
  try {
    if (circuitBreakerState.isOpen) {
      const now = Date.now();
      if (
        now - circuitBreakerState.lastFailureTime >
        circuitBreakerState.timeout
      ) {
        circuitBreakerState.isOpen = false;
        circuitBreakerState.failureCount = 0;
        console.log("Circuit breaker reset - attempting reconnection");
      } else {
        return false;
      }
    }

    await redis.ping();
    connectionHealth.isConnected = true;
    connectionHealth.lastPing = Date.now();
    connectionHealth.consecutiveFailures = 0;
    circuitBreakerState.failureCount = 0;
    return true;
  } catch (error) {
    connectionHealth.isConnected = false;
    connectionHealth.consecutiveFailures++;
    circuitBreakerState.failureCount++;
    circuitBreakerState.lastFailureTime = Date.now();

    if (circuitBreakerState.failureCount >= circuitBreakerState.threshold) {
      circuitBreakerState.isOpen = true;
      console.error("Circuit breaker opened - Redis connection failed");
    }

    console.error("Redis health check failed:", error);
    return false;
  }
}

setInterval(async () => {
  await checkRedisHealth();
}, 30000);

// Handle Redis connection events
redis.on("connect", () => {
  console.log("Redis connected successfully");
  connectionHealth.isConnected = true;
  connectionHealth.consecutiveFailures = 0;
  circuitBreakerState.isOpen = false;
  circuitBreakerState.failureCount = 0;
});

redis.on("ready", () => {
  console.log("Redis ready to accept commands");
  connectionHealth.isConnected = true;
});

redis.on("error", (error: Error) => {
  console.error("Redis connection error:", error);
  connectionHealth.isConnected = false;
  connectionHealth.consecutiveFailures++;

  // Update circuit breaker
  circuitBreakerState.failureCount++;
  circuitBreakerState.lastFailureTime = Date.now();

  if (circuitBreakerState.failureCount >= circuitBreakerState.threshold) {
    circuitBreakerState.isOpen = true;
    console.error("Circuit breaker opened due to Redis errors");
  }
});

redis.on("close", () => {
  console.log("Redis connection closed");
  connectionHealth.isConnected = false;
});

redis.on("reconnecting", (delay: number) => {
  console.log(`🔄 Redis reconnecting in ${delay}ms`);
});

redis.on("end", () => {
  console.log("🔚 Redis connection ended");
  connectionHealth.isConnected = false;
});

// Graceful shutdown
export async function closeRedisConnection(): Promise<void> {
  try {
    await redis.quit();
    console.log("✅ Redis connection closed gracefully");
  } catch (error) {
    console.error("Error closing Redis connection:", error);
    redis.disconnect();
  }
}

export function getRedisStatus() {
  return {
    isConnected: connectionHealth.isConnected,
    lastPing: connectionHealth.lastPing,
    consecutiveFailures: connectionHealth.consecutiveFailures,
    circuitBreakerOpen: circuitBreakerState.isOpen,
    failureCount: circuitBreakerState.failureCount,
  };
}

export default redis;

import type { Request, Response, NextFunction } from "express";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

declare global {
  namespace Express {
    interface Request {
      user?: {
        id: string;
        email: string;
      };
    }
  }
}

export async function authenticateUser(
  req: Request,
  res: Response,
  next: NextFunction
) {
  try {
    const userId =
      req.headers["x-user-id"] || req.body.userId || req.query.userId;

    if (!userId) {
      return res.status(401).json({
        success: false,
        error: "User ID required",
        message: "Please provide user ID in headers, body, or query parameters",
      });
    }

    if (typeof userId !== "string") {
      return res.status(400).json({
        success: false,
        error: "Invalid user ID format",
        message: "Clerk user ID must be a string",
      });
    }

    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        email: true,
      },
    });

    if (!user) {
      return res.status(404).json({
        success: false,
        error: "User not found",
      });
    }

    req.user = user;
    next();
  } catch (error) {
    console.error("Authentication error:", error);
    return res.status(500).json({
      success: false,
      error: "Authentication failed",
    });
  }
}

export async function optionalAuth(
  req: Request,
  res: Response,
  next: NextFunction
) {
  try {
    const userId =
      req.headers["x-user-id"] || req.body.userId || req.query.userId;

    if (!userId) {
      return next();
    }

    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        email: true,
      },
    });

    if (user) {
      req.user = user;
    }

    next();
  } catch (error) {
    console.error("Optional authentication error:", error);
    next();
  }
}

export function rateLimit(requestsPerMinute: number = 60) {
  const requests = new Map<string, { count: number; resetTime: number }>();

  return (req: Request, res: Response, next: NextFunction) => {
    const userId = req.user?.id || req.ip || "anonymous";
    const now = Date.now();
    const windowMs = 60 * 1000; // 1 minute

    const userRequests = requests.get(userId.toString());

    if (!userRequests || now > userRequests.resetTime) {
      // Reset or initialize
      requests.set(userId.toString(), {
        count: 1,
        resetTime: now + windowMs,
      });
    } else if (userRequests.count >= requestsPerMinute) {
      return res.status(429).json({
        success: false,
        error: "Rate limit exceeded",
        message: `Maximum ${requestsPerMinute} requests per minute allowed`,
        retryAfter: Math.ceil((userRequests.resetTime - now) / 1000),
      });
    } else {
      userRequests.count++;
    }

    next();
  };
}

export async function requireAdmin(
  req: Request,
  res: Response,
  next: NextFunction
) {
  try {
    await authenticateUser(req, res, (err) => {
      if (err) return next(err);
    });

    const isAdmin = Boolean(req.user?.email?.includes("admin"));

    if (!isAdmin) {
      return res.status(403).json({
        success: false,
        error: "Admin access required",
      });
    }

    next();
  } catch (error) {
    console.error("Admin authentication error:", error);
    return res.status(500).json({
      success: false,
      error: "Admin authentication failed",
    });
  }
}

