  if (autoScaleInterval) return;

  autoScaleInterval = setInterval(async () => {
    try {
      await QueueService.autoScale();
    } catch (error) {
      console.error("Auto-scaling error:", error);
    }
  }, 2 * 60 * 1000);
}

