"use client";

import { useState, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useMutation } from "@tanstack/react-query";
import Link from "next/link";

import { clientApi } from "@/lib/client/api";
import { validatePassword } from "@/lib/validation";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Field,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@/components/ui/field";
import { Input } from "@/components/ui/input";

function ResetPasswordLogic() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const token = searchParams.get("token") || "";

  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [formError, setFormError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  const mutation = useMutation({
    mutationFn: async () => {
      if (!token) {
        throw new Error(
          "Invalid reset link. Please request a new password reset.",
        );
      }
      if (!password) {
        throw new Error("Please enter a new password.");
      }

      const passwordError = validatePassword(password);
      if (passwordError) {
        throw new Error(passwordError);
      }

      if (password !== confirmPassword) {
        throw new Error("Passwords do not match.");
      }
      return clientApi.resetPassword({ token, password });
    },
    onSuccess: () => {
      setFormError(null);
      setSuccess(true);
    },
    onError: (error: unknown) => {
      setFormError(
        error instanceof Error ? error.message : "Password reset failed.",
      );
    },
  });

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    mutation.mutate();
  };

  if (!token) {
    return (
      <div className="border-border bg-card/60 space-y-6 rounded-2xl border p-8 shadow-sm backdrop-blur">
        <div className="text-center">
          <h1 className="text-foreground text-2xl font-semibold">
            Invalid reset link
          </h1>
          <p className="text-muted-foreground mt-2 text-sm">
            This password reset link is invalid or has expired.
          </p>
        </div>
        <Link href="/forgot-password" className="block">
          <Button className="w-full">Request new reset link</Button>
        </Link>
      </div>
    );
  }

  if (success) {
    return (
      <div className="border-border bg-card/60 space-y-6 rounded-2xl border p-8 shadow-sm backdrop-blur">
        <div className="text-center">
          <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-green-500/10">
            <svg
              className="h-6 w-6 text-green-500"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M5 13l4 4L19 7"
              />
            </svg>
          </div>
          <h1 className="text-foreground text-2xl font-semibold">
            Password reset!
          </h1>
          <p className="text-muted-foreground mt-2 text-sm">
            Your password has been successfully reset.
          </p>
        </div>
        <Link href="/login" className="block">
          <Button className="w-full">Sign in with new password</Button>
        </Link>
      </div>
    );
  }

  return (
    <div className="border-border bg-card/60 space-y-6 rounded-2xl border p-8 shadow-sm backdrop-blur">
      <div>
        <h1 className="text-foreground text-2xl font-semibold">
          Set new password
        </h1>
        <p className="text-muted-foreground mt-2 text-sm">
          Enter your new password below.
        </p>
      </div>

      <form onSubmit={handleSubmit} className="grid gap-6">
        <FieldGroup>
          <Field data-invalid={!!formError && !password}>
            <FieldLabel htmlFor="password">New password</FieldLabel>
            <Input
              id="password"
              name="password"
              type="password"
              placeholder="At least 8 characters"
              autoComplete="new-password"
              value={password}
              onChange={(event) => setPassword(event.target.value)}
              aria-invalid={!!formError && !password}
              required
            />
            {!password && formError && (
              <FieldError>Password is required.</FieldError>
            )}
          </Field>
          <Field data-invalid={!!formError && password !== confirmPassword}>
            <FieldLabel htmlFor="confirmPassword">Confirm password</FieldLabel>
            <Input
              id="confirmPassword"
              name="confirmPassword"
              type="password"
              placeholder="Re-enter your password"
              autoComplete="new-password"
              value={confirmPassword}
              onChange={(event) => setConfirmPassword(event.target.value)}
              aria-invalid={!!formError && password !== confirmPassword}
              required
            />
          </Field>
        </FieldGroup>

        {formError && (
          <Alert variant="destructive">
            <AlertTitle>Reset failed</AlertTitle>
            <AlertDescription>{formError}</AlertDescription>
          </Alert>
        )}

        <Button type="submit" className="w-full" disabled={mutation.isPending}>
          {mutation.isPending ? "Resetting..." : "Reset password"}
        </Button>

        <div className="text-center">
          <Link
            href="/login"
            className="text-muted-foreground hover:text-foreground text-sm font-medium transition"
          >
            Back to sign in
          </Link>
        </div>
      </form>
    </div>
  );
}

export function ResetPasswordContent() {
  return (
    <Suspense
      fallback={
        <div className="flex flex-col items-center justify-center p-8 text-center">
          <div className="border-primary mb-4 h-8 w-8 animate-spin rounded-full border-b-2" />
          <p className="text-muted-foreground">Loading...</p>
        </div>
      }
    >
      <ResetPasswordLogic />
    </Suspense>
  );
}

"use client";

import { useState, useRef, useEffect, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useMutation } from "@tanstack/react-query";
import Link from "next/link";

import { clientApi } from "@/lib/client/api";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

function VerifyEmailLogic() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const emailFromParams = searchParams.get("email") || "";

  const [otp, setOtp] = useState(["", "", "", "", "", ""]);
  const [formError, setFormError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [resendSuccess, setResendSuccess] = useState(false);
  const [resendTimer, setResendTimer] = useState(0);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

  useEffect(() => {
    inputRefs.current[0]?.focus();
  }, []);

  useEffect(() => {
    if (resendTimer > 0) {
      const timer = setTimeout(() => setResendTimer(resendTimer - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [resendTimer]);

  const handleChange = (index: number, value: string) => {
    if (!/^\d*$/.test(value)) return;

    const newOtp = [...otp];
    newOtp[index] = value.slice(-1);
    setOtp(newOtp);

    if (value && index < 5) {
      inputRefs.current[index + 1]?.focus();
    }
  };

  const handleKeyDown = (
    index: number,
    e: React.KeyboardEvent<HTMLInputElement>,
  ) => {
    if (e.key === "Backspace" && !otp[index] && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    e.preventDefault();
    const pastedData = e.clipboardData
      .getData("text")
      .replace(/\D/g, "")
      .slice(0, 6);
    if (pastedData.length === 6) {
      setOtp(pastedData.split(""));
      inputRefs.current[5]?.focus();
    }
  };

  const mutation = useMutation({
    mutationFn: async () => {
      const code = otp.join("");
      if (!emailFromParams) {
        throw new Error("Email is missing. Please go back and register again.");
      }
      if (code.length !== 6) {
        throw new Error("Please enter the complete 6-digit code.");
      }
      return clientApi.verifyEmail({ email: emailFromParams, otp: code });
    },
    onSuccess: () => {
      setFormError(null);
      setSuccess(true);
      setTimeout(() => {
        router.replace("/dashboard");
        router.refresh();
      }, 2000);
    },
    onError: (error: unknown) => {
      setFormError(
        error instanceof Error ? error.message : "Verification failed.",
      );
    },
  });

  const resendMutation = useMutation({
    mutationFn: async () => {
      if (!emailFromParams) {
        throw new Error("Email is missing.");
      }
      return clientApi.resendVerificationEmail({ email: emailFromParams });
    },
    onSuccess: () => {
      setResendSuccess(true);
      setFormError(null);
      setTimeout(() => setResendSuccess(false), 5000);
    },
    onError: (error: unknown) => {
      setFormError(
        error instanceof Error ? error.message : "Failed to resend code.",
      );
    },
  });

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    mutation.mutate();
  };

  const handleResend = () => {
    if (resendTimer > 0) return;
    setResendTimer(30);
    resendMutation.mutate();
  };

  if (success) {
    return (
      <div className="border-border bg-card/60 space-y-6 rounded-2xl border p-8 shadow-sm backdrop-blur">
        <div className="text-center">
          <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-green-500/10">
            <svg
              className="h-8 w-8 text-green-500"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M5 13l4 4L19 7"
              />
            </svg>
          </div>
          <h1 className="text-foreground text-2xl font-semibold">
            Email Verified!
          </h1>
          <p className="text-muted-foreground mt-2 text-sm">
            Redirecting you to the dashboard...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="border-border bg-card/60 space-y-6 rounded-2xl border p-8 shadow-sm backdrop-blur">
      <div className="text-center">
        <div className="bg-primary/10 mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full">
          <svg
            className="text-primary h-8 w-8"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"
            />
          </svg>
        </div>
        <h1 className="text-foreground text-2xl font-semibold">
          Verify your email
        </h1>
        <p className="text-muted-foreground mt-2 text-sm">
          We sent a 6-digit code to
        </p>
        <p className="text-foreground mt-1 font-medium">{emailFromParams}</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="flex justify-center gap-2" onPaste={handlePaste}>
          {otp.map((digit, index) => (
            <input
              key={index}
              ref={(el) => {
                inputRefs.current[index] = el;
              }}
              type="text"
              inputMode="numeric"
              maxLength={1}
              value={digit}
              onChange={(e) => handleChange(index, e.target.value)}
              onKeyDown={(e) => handleKeyDown(index, e)}
              className="border-border bg-background text-foreground focus:border-primary focus:ring-primary/20 h-14 w-12 rounded-lg border-2 text-center text-2xl font-bold transition-all focus:ring-2 focus:outline-none"
              aria-label={`Digit ${index + 1}`}
            />
          ))}
        </div>

        {formError && (
          <Alert variant="destructive">
            <AlertTitle>Verification failed</AlertTitle>
            <AlertDescription>{formError}</AlertDescription>
          </Alert>
        )}

        {resendSuccess && (
          <Alert className="border-green-500/50 text-green-600 dark:border-green-500/30 dark:text-green-400">
            <AlertTitle>Code sent!</AlertTitle>
            <AlertDescription>
              Please check your email for the new code.
            </AlertDescription>
          </Alert>
        )}

        <Button
          type="submit"
          className="w-full"
          disabled={mutation.isPending || otp.join("").length !== 6}
        >
          {mutation.isPending ? "Verifying..." : "Verify email"}
        </Button>

        <div className="space-y-2 text-center">
          <p className="text-muted-foreground text-sm">
            Didn&apos;t receive a code?{" "}
            <button
              type="button"
              onClick={handleResend}
              disabled={resendMutation.isPending || resendTimer > 0}
              className="text-primary hover:text-primary/80 font-semibold transition disabled:cursor-not-allowed disabled:opacity-50"
            >
              {resendMutation.isPending
                ? "Resending..."
                : resendTimer > 0
                  ? `Resend in ${resendTimer}s`
                  : "Resend"}
            </button>
          </p>
          <p className="text-muted-foreground text-sm">
            Please check your spam folder as well.
          </p>
          <Link
            href="/login"
            className="text-muted-foreground hover:text-foreground inline-block text-sm font-medium transition"
          >
            Back to sign in
          </Link>
        </div>
      </form>
    </div>
  );
}

export function VerifyEmailContent() {
  return (
    <Suspense
      fallback={
        <div className="flex flex-col items-center justify-center p-8 text-center">
          <div className="border-primary mb-4 h-8 w-8 animate-spin rounded-full border-b-2" />
          <p className="text-muted-foreground">Loading...</p>
        </div>
      }
    >
      <VerifyEmailLogic />
    </Suspense>
  );
}

