apiRouter.use("/keyword-schedule", keywordScheduleRouter);
apiRouter.use("/keyword-stats", keywordStatsRouter);
apiRouter.use("/keyword-monitors", keywordMonitorRouter);
apiRouter.use("/keyword-leads", keywordLeadRouter);

// Admin routes (protected by API key)
apiRouter.use("/admin", adminRouter);

// Lead Gen scheduler (hourly at xx:00)
const leadGenScheduler = cron.schedule(CRON_INTERVAL, runScheduler, {
  timezone: "UTC",
});

const keywordScheduler = cron.schedule(
  KEYWORD_CRON_INTERVAL,
  runKeywordScheduler,
  {
    timezone: "UTC",
  },
);

// Hourly Log Report (at xx:00)
cron.schedule(
  "0 * * * *",
  async () => {
    logger.info("Running hourly log report");
    await sendAllLogsToDiscord("backend");
  },
  { timezone: "UTC" },
);

const server = app.listen(PORT, () => {
  logger.info(`Server is running on port ${PORT}`);
  logger.info("Lead Gen Scheduler started (hourly at xx:00).");
  logger.info("Keyword Scheduler started (hourly at xx:30).");
});

const stopServer = async () => {
  leadGenScheduler.stop();
  keywordScheduler.stop();

  // Stop accepting new connections first, then close dependencies
  server.close(async () => {
    await closeRedis().catch(() => {});
    await db.$disconnect().catch(() => {});
    logger.info("Server closed.");
    process.exit(0);
  });

  // Force exit if graceful shutdown takes too long
  setTimeout(() => {
    logger.warn("Forced exit after timeout.");
    process.exit(1);
  }, 10000);
};

process.on("SIGINT", () => {
  logger.info("SIGINT received, stopping scheduler...");
  stopServer();
});

process.on("SIGTERM", () => {
  logger.info("SIGTERM received, stopping scheduler...");
  stopServer();
});

import { Request, Response } from "express";
import logger from "../lib/logger";
import db from "../lib/db";
import { patchAccountSchema, patchProfileSchema } from "../types/account";
import { previewUsage } from "../lib/usage";
import { SubscriptionTier } from "@prisma/client";

export async function getAccount(req: Request, res: Response) {
  try {
    const userId = req.userId;
    const findExistingUser = await db.user.findFirst({
      where: {
        id: userId,
      },
    });

    if (!findExistingUser) {
      return res.status(400).json({ error: "User does not exist" });
    }

    const user = {
      data: {
        id: findExistingUser?.id,
        name: findExistingUser?.name,
        email: findExistingUser?.email,
        emailVerified: findExistingUser?.emailVerified,
        image: findExistingUser?.image,
        createdAt: findExistingUser?.createdAt,
        hasSeenWalkthrough:
          (findExistingUser as any).hasSeenWalkthrough ?? false,
        hasCompletedOnboarding:
          findExistingUser?.hasCompletedOnboarding ?? false,
        company: findExistingUser?.company ?? null,
        occupation: findExistingUser?.occupation ?? null,
        referrer: findExistingUser?.referrer ?? null,
        sampleDm: findExistingUser?.sampleDm ?? null,
      },
    };

    res
      .status(200)
      .json({ message: "User retrieved successfully", payload: user });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
}

export async function patchAccount(req: Request, res: Response) {
  try {
    const userId = req.userId;
    const findExistingUser = await db.user.findFirst({
      where: {
        id: userId,
      },
    });

    if (!findExistingUser) {
      return res.status(400).json({ error: "User does not exist" });
    }

    const payload = patchAccountSchema.safeParse(req.body);
    if (!payload.success) {
      return res.status(400).json({
        error: "Invalid request body",
      });
    }

    if (payload.data.name === findExistingUser.name) {
      return res.status(400).json({ error: "Name is unchanged." });
    }

    const updatedUser = await db.user.update({
      where: {
        id: userId,
      },
      data: {
        name: payload.data.name,
      },
    });

    res.status(200).json({
      message: "Account updated successfully.",
      payload: {
        id: userId,
        name: updatedUser.name,
        email: updatedUser.email,
      },
    });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
}

export async function deleteAccount(req: Request, res: Response) {
  try {
    const userId = req.userId;
    const findExistingUser = await db.user.findFirst({
      where: {
        id: userId,
      },
    });

    if (!findExistingUser) {
      return res.status(400).json({ error: "User does not exist" });
    }
    await db.user.update({
      where: {
        id: userId,
      },
      data: {
        isDeleted: true,
      },
