import { Request, Response } from "express";
import logger from "../lib/logger";
import {
  registerSchema,
  loginSchema,
  verifyEmailSchema,
  resendVerificationEmailSchema,
  forgotPasswordSchema,
  resetPasswordSchema,
  formatZodError,
} from "../types/schema";
import db from "../lib/db";
import bcrypt from "bcrypt";
import crypto from "crypto";
