// const isDevelopment = env.NODE_ENV === "development";
const isDevelopment = false; // turn this on when testing non registration

function generateSecureSessionToken(): string {
  return crypto.randomBytes(32).toString("hex");
}

const MAX_SESSIONS = 5;

export async function createUserSession(userId: string) {
  const token = generateSecureSessionToken();
  const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days from now

  // Clean up expired sessions
  await db.session.deleteMany({
    where: {
      userId,
      expiresAt: {
        lt: new Date(),
      },
    },
  });

  // Cap active sessions — keep only the newest (MAX_SESSIONS - 1) so the new one makes MAX_SESSIONS
  const activeSessions = await db.session.findMany({
    where: { userId },
    orderBy: { createdAt: "desc" },
    select: { id: true },
  });
  if (activeSessions.length >= MAX_SESSIONS - 1) {
    const idsToKeep = activeSessions
      .slice(0, MAX_SESSIONS - 1)
      .map((s) => s.id);
    await db.session.deleteMany({
      where: { userId, id: { notIn: idsToKeep } },
    });
  }

  return await db.session.create({
    data: {
      id: crypto.randomUUID(),
      token,
      userId,
      expiresAt,
    },
  });
}

export function getCookieOptions(maxAge: number = 1000 * 60 * 60 * 24 * 7) {
  const isProduction = process.env.NODE_ENV === "production";
  return {
    httpOnly: true,
    secure: isProduction,
    sameSite: isProduction ? "none" : "lax",
    domain: isProduction ? ".leadly.live" : undefined,
    maxAge,
    path: "/",
  } as const;
}

export async function register(req: Request, res: Response) {
  try {
    const payload = registerSchema.safeParse(req.body);
    if (!payload.success) {
      return res.status(400).json({ error: formatZodError(payload.error) });
    }

    const email = payload.data.email.toLowerCase();
    const rateLimitCheck = await checkRateLimit(req, "register");
    if (rateLimitCheck.exceeded) {
      return res.status(429).json({
        error: rateLimitCheck.error,
        retryAfter: rateLimitCheck.retryAfter,
      });
    }

    const findExistingUser = await db.user.findUnique({
      where: {
        email,
      },
    });

    if (findExistingUser?.isDeleted) {
      return res.status(400).json({ error: "User is deleted" });
    }

    if (findExistingUser && findExistingUser.emailVerified) {
      return res.status(400).json({ error: "User already exists" });
    }

    const emailValidation = await validateEmail(email);
    if (!emailValidation.valid) {
      return res.status(400).json({ error: emailValidation.reason });
    }

    const hashedPassword = await bcrypt.hash(payload.data.password, 10);
    const otp = crypto.randomInt(100000, 999999).toString();
    const otpExpiresAt = new Date(Date.now() + 10 * 60 * 1000); // 10 minutes

    // If unverified user exists, update instead of delete to prevent race condition
    if (findExistingUser && !findExistingUser.emailVerified) {
      const token = generateSecureSessionToken();
      const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

      const { user, session } = await db.$transaction(async (tx) => {
        const user = await tx.user.update({
          where: { id: findExistingUser.id },
          data: {
            name: payload.data.name,
            passwordHash: hashedPassword,
            // In development, auto-verify; in production, require OTP
            emailVerified: isDevelopment,
            emailOtp: isDevelopment ? null : otp,
            emailOtpExpiresAt: isDevelopment ? null : otpExpiresAt,
          },
        });

        await tx.session.deleteMany({ where: { userId: user.id } });

        const session = await tx.session.create({
          data: {
            id: crypto.randomUUID(),
            token,
            userId: user.id,
            expiresAt,
          },
        });

        return { user, session };
      });

      // Only send verification email in production
      if (!isDevelopment) {
        try {
          await sendVerificationEmail(email, otp);
          await incrementRateLimit(req, "register");
        } catch (emailError) {
          logger.error("Failed to send verification email:", emailError);
        }
      }

      return res
        .cookie("session_token", session.token, getCookieOptions())
        .status(200)
        .json({
          message: isDevelopment
            ? "User registered (dev mode - auto-verified)"
            : "Verification email resent",
          email: user.email,
        });
    }

    const { user, session } = await db.$transaction(async (tx) => {
      const user = await tx.user.create({
        data: {
          name: payload.data.name,
          email,
          passwordHash: hashedPassword as string,
          // In development, auto-verify; in production, require OTP
          emailVerified: isDevelopment,
          emailOtp: isDevelopment ? null : otp,
          emailOtpExpiresAt: isDevelopment ? null : otpExpiresAt,
        },
      });

      const token = generateSecureSessionToken();
      const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

      await tx.session.deleteMany({
        where: {
          userId: user.id,
          expiresAt: {
            lt: new Date(),
          },
        },
      });

      const session = await tx.session.create({
        data: {
          id: crypto.randomUUID(),
          token,
          userId: user.id,
          expiresAt,
        },
      });

      await tx.subscription.create({
        data: {
          userId: user.id,
          status: SubscriptionStatus.ACTIVE,
          tier: SubscriptionTier.FREE,
          currentPeriodEnd: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000),
        },
      });

      await initializeOrResetUsagePeriod(tx, user.id, SubscriptionTier.FREE);

      await tx.userSchedule.create({
        data: {
          userId: user.id,
          scheduledHours: [12],
        },
      });

      return { user, session };
    });

    // Only send verification email in production
    if (!isDevelopment) {
      try {
        await sendVerificationEmail(email, otp);
        await incrementRateLimit(req, "register");
      } catch (emailError) {
        logger.error("Failed to send verification email:", emailError);
      }
    }

    res
      .cookie("session_token", session.token, getCookieOptions())
      .status(201)
      .json({
        message: isDevelopment
          ? "User created successfully (dev mode - auto-verified)"
          : "User created successfully",
        email: user.email,
      });
  } catch (error) {
    logger.error("Registration failed:", error);
    res.status(500).json({ error: "Internal server error" });
  }
}

export async function login(req: Request, res: Response) {
  try {
    const payload = loginSchema.safeParse(req.body);
    if (!payload.success) {
      return res.status(400).json({ error: formatZodError(payload.error) });
    }

    const email = payload.data.email.toLowerCase();

    const userInDb = await db.user.findUnique({
      where: {
        email,
      },
    });

    if (!userInDb) {
      await bcrypt.compare(
        payload.data.password,
        "$2b$10$dummyhashtopreventtimingattacks",
      );
      return res.status(400).json({ error: "Invalid email or password" });
    }
    if (userInDb?.isDeleted) {
      return res.status(400).json({ error: "Invalid email or password" });
    }

    // OAuth-only users have empty passwordHash — bcrypt.compare would throw
    if (!userInDb.passwordHash) {
      return res.status(400).json({ error: "Invalid email or password" });
    }

    const isPasswordValid = await bcrypt.compare(
      payload.data.password,
      userInDb.passwordHash,
    );

    if (!isPasswordValid) {
      return res.status(400).json({ error: "Invalid email or password" });
    }

    // Allow both verified and unverified users to log in
    // Unverified users will be restricted at the route level for protected operations
    const session = await createUserSession(userInDb.id);

    res
      .cookie("session_token", session.token, getCookieOptions())
      .status(200)
      .json({
        message: "Login successful",
        emailVerified: userInDb.emailVerified,
      });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
}

export async function logout(req: Request, res: Response) {
  try {
    const sessionToken = req.cookies.session_token;
    if (!sessionToken) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    await db.session.deleteMany({
      where: {
        token: sessionToken,
      },
    });

    res
      .cookie("session_token", "", getCookieOptions(0))
      .status(200)
      .json({ message: "Logout successful" });
  } catch (error) {
    logger.error("LOGOUT_ERROR:", error);
    res.status(500).json({ error: "Internal server error" });
  }
}

export async function verifyEmail(req: Request, res: Response) {
  try {
    const payload = verifyEmailSchema.safeParse(req.body);
    if (!payload.success) {
      return res.status(400).json({ error: formatZodError(payload.error) });
    }

    const email = payload.data.email.toLowerCase();

    const user = await db.user.findUnique({
      where: { email },
    });

    if (!user) {
      return res.status(400).json({ error: "User not found" });
    }

    if (user.isDeleted) {
      return res.status(400).json({ error: "User is deleted" });
    }

    if (user.emailVerified) {
      return res.status(400).json({ error: "Email already verified" });
    }

    if (!user.emailOtp || !user.emailOtpExpiresAt) {
      return res.status(400).json({ error: "No verification code found" });
    }

    if (new Date() > user.emailOtpExpiresAt) {
      return res.status(400).json({ error: "Verification code has expired" });
    }

    if (user.emailOtp !== payload.data.otp) {
      return res.status(400).json({ error: "Invalid verification code" });
    }

    await db.user.update({
      where: { id: user.id },
      data: {
        emailVerified: true,
        emailOtp: null,
        emailOtpExpiresAt: null,
      },
    });

    res.status(200).json({ message: "Email verified successfully" });
  } catch (error) {
    logger.error("Email verification failed:", error);
    res.status(500).json({ error: "Internal server error" });
  }
}

